// Approach: Multi-source BFS starting from every zero cell, so each cell is reached by its nearest zero first.
// Time O(m * n), Space O(m * n)
class Solution {
public:
    vector<vector<int>> updateMatrix(vector<vector<int>>& mat) {
        int m = mat.size();
        int n = mat[0].size();
        vector<vector<int>> dist(m, vector<int>(n, -1));
        queue<pair<int, int>> queue;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 0) {
                    dist[i][j] = 0;
                    queue.push({i, j});
                }
            }
        }
        const int rowStep[4] = {1, -1, 0, 0};
        const int colStep[4] = {0, 0, 1, -1};
        while (!queue.empty()) {
            auto [row, col] = queue.front();
            queue.pop();
            for (int d = 0; d < 4; d++) {
                int nextRow = row + rowStep[d];
                int nextCol = col + colStep[d];
                bool inside = nextRow >= 0 && nextRow < m && nextCol >= 0 && nextCol < n;
                if (inside && dist[nextRow][nextCol] < 0) {
                    dist[nextRow][nextCol] = dist[row][col] + 1;
                    queue.push({nextRow, nextCol});
                }
            }
        }
        return dist;
    }
};

// Approach: Sort, fix the first two numbers, then close in with two pointers while skipping duplicates.
// Time O(n^3), Space O(1) extra (excluding output)
class Solution {
public:
    vector<vector<int>> fourSum(vector<int>& nums, int target) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<vector<int>> result;
        for (int i = 0; i + 3 < n; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            for (int j = i + 1; j + 2 < n; j++) {
                if (j > i + 1 && nums[j] == nums[j - 1]) continue;
                int low = j + 1;
                int high = n - 1;
                while (low < high) {
                    long long sum = (long long)nums[i] + nums[j] + nums[low] + nums[high];
                    if (sum < target) {
                        low++;
                    } else if (sum > target) {
                        high--;
                    } else {
                        result.push_back({nums[i], nums[j], nums[low], nums[high]});
                        low++;
                        high--;
                        while (low < high && nums[low] == nums[low - 1]) low++;
                    }
                }
            }
        }
        return result;
    }
};

// Approach: Post-order DFS returning the subtree height, or -1 as soon as any subtree is unbalanced.
// Time O(n), Space O(h) where h is the tree height
int heightOrUnbalanced(TreeNode* node) {
    if (!node) return 0;
    int leftHeight = heightOrUnbalanced(node->left);
    if (leftHeight < 0) return -1;
    int rightHeight = heightOrUnbalanced(node->right);
    if (rightHeight < 0 || abs(leftHeight - rightHeight) > 1) return -1;
    return 1 + max(leftHeight, rightHeight);
}

class Solution {
public:
    bool isBalanced(TreeNode* root) {
        return heightOrUnbalanced(root) >= 0;
    }
};

// Approach: Track the best profit after each of the four states: first buy, first sell, second buy, second sell.
// Time O(n), Space O(1)
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int firstBuy = INT_MIN / 2;
        int secondBuy = INT_MIN / 2;
        int firstSell = 0;
        int secondSell = 0;
        for (int price : prices) {
            firstBuy = max(firstBuy, -price);
            firstSell = max(firstSell, firstBuy + price);
            secondBuy = max(secondBuy, firstSell - price);
            secondSell = max(secondSell, secondBuy + price);
        }
        return secondSell;
    }
};

// Approach: Iterative inorder traversal using an explicit stack of the left spine.
// Time O(n), Space O(h) where h is the tree height
class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> result;
        vector<TreeNode*> stack;
        TreeNode* node = root;
        while (node || !stack.empty()) {
            while (node) {
                stack.push_back(node);
                node = node->left;
            }
            node = stack.back();
            stack.pop_back();
            result.push_back(node->val);
            node = node->right;
        }
        return result;
    }
};

// Approach: Level-order BFS, keeping the last node of each level.
// Time O(n), Space O(w) where w is the maximum level width
class Solution {
public:
    vector<int> rightSideView(TreeNode* root) {
        vector<int> result;
        if (!root) return result;
        queue<TreeNode*> queue;
        queue.push(root);
        while (!queue.empty()) {
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                TreeNode* node = queue.front();
                queue.pop();
                if (i == levelSize - 1) result.push_back(node->val);
                if (node->left) queue.push(node->left);
                if (node->right) queue.push(node->right);
            }
        }
        return result;
    }
};

// Approach: Interval DP choosing the last balloon to burst in each open interval, with 1s as sentinels.
// Time O(n^3), Space O(n^2)
class Solution {
public:
    int maxCoins(vector<int>& nums) {
        vector<int> balloons;
        balloons.push_back(1);
        for (int value : nums) balloons.push_back(value);
        balloons.push_back(1);
        int n = balloons.size();
        // dp[left][right]: best coins from bursting everything strictly between left and right
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int length = 2; length < n; length++) {
            for (int left = 0; left + length < n; left++) {
                int right = left + length;
                for (int last = left + 1; last < right; last++) {
                    int coins = balloons[left] * balloons[last] * balloons[right];
                    int total = dp[left][last] + coins + dp[last][right];
                    dp[left][right] = max(dp[left][right], total);
                }
            }
        }
        return dp[0][n - 1];
    }
};

// Approach: Binary search on the ship capacity, greedily counting the days each capacity needs.
// Time O(n log(sum of weights)), Space O(1)
class Solution {
public:
    int shipWithinDays(vector<int>& weights, int days) {
        long long low = *max_element(weights.begin(), weights.end());
        long long high = 0;
        for (int weight : weights) high += weight;
        while (low < high) {
            long long capacity = (low + high) / 2;
            long long load = 0;
            int daysNeeded = 1;
            for (int weight : weights) {
                if (load + weight > capacity) {
                    daysNeeded++;
                    load = 0;
                }
                load += weight;
            }
            if (daysNeeded <= days) {
                high = capacity;
            } else {
                low = capacity + 1;
            }
        }
        return low;
    }
};

// Approach: Fibonacci recurrence, keeping only the ways to reach the previous two steps.
// Time O(n), Space O(1)
class Solution {
public:
    int climbStairs(int n) {
        int waysTwoBack = 1;
        int waysOneBack = 1;
        for (int step = 1; step < n; step++) {
            int ways = waysOneBack + waysTwoBack;
            waysTwoBack = waysOneBack;
            waysOneBack = ways;
        }
        return waysOneBack;
    }
};

// Approach: Backtracking over sorted candidates, reusing the same index and pruning once a value exceeds the remainder.
// Time O(N^(target / min candidate)) in the worst case, Space O(target / min candidate) recursion depth
void collectCombinations(const vector<int>& candidates, int start, int remaining,
                         vector<int>& current, vector<vector<int>>& result) {
    if (remaining == 0) {
        result.push_back(current);
        return;
    }
    for (int i = start; i < (int)candidates.size(); i++) {
        if (candidates[i] > remaining) break;
        current.push_back(candidates[i]);
        collectCombinations(candidates, i, remaining - candidates[i], current, result);
        current.pop_back();
    }
}

class Solution {
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end());
        vector<int> current;
        vector<vector<int>> result;
        collectCombinations(candidates, 0, target, current, result);
        return result;
    }
};

// Approach: Insert into a hash set and stop at the first value that is already present.
// Time O(n), Space O(n)
class Solution {
public:
    bool containsDuplicate(vector<int>& nums) {
        unordered_set<int> seen;
        for (int value : nums) {
            if (!seen.insert(value).second) return true;
        }
        return false;
    }
};

// Approach: DFS carrying the maximum value on the path; a node is good if it is at least that maximum.
// Time O(n), Space O(h) where h is the tree height
int countGood(TreeNode* node, int maxOnPath) {
    if (!node) return 0;
    int good = node->val >= maxOnPath ? 1 : 0;
    maxOnPath = max(maxOnPath, node->val);
    return good + countGood(node->left, maxOnPath) + countGood(node->right, maxOnPath);
}

class Solution {
public:
    int goodNodes(TreeNode* root) {
        return countGood(root, INT_MIN);
    }
};

// Approach: DP where bits(i) = bits(i / 2) plus the lowest bit of i.
// Time O(n), Space O(n)
class Solution {
public:
    vector<int> countBits(int n) {
        vector<int> bits(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            bits[i] = bits[i >> 1] + (i & 1);
        }
        return bits;
    }
};

// Approach: Rolling DP over prefixes, adding one-digit and valid two-digit decodings.
// Time O(n), Space O(1)
class Solution {
public:
    int numDecodings(string s) {
        long long waysTwoBack = 0;
        long long waysOneBack = 1;
        for (int i = 0; i < (int)s.size(); i++) {
            long long ways = s[i] != '0' ? waysOneBack : 0;
            if (i > 0) {
                int twoDigits = (s[i - 1] - '0') * 10 + (s[i] - '0');
                if (twoDigits >= 10 && twoDigits <= 26) ways += waysTwoBack;
            }
            waysTwoBack = waysOneBack;
            waysOneBack = ways;
        }
        return waysOneBack;
    }
};

// Approach: Backtracking over a sorted array, skipping a duplicate unless its equal predecessor is in use.
// Time O(n * n!), Space O(n)
void collectPermutations(const vector<int>& nums, vector<bool>& used, vector<int>& current,
                         vector<vector<int>>& result) {
    if (current.size() == nums.size()) {
        result.push_back(current);
        return;
    }
    for (int i = 0; i < (int)nums.size(); i++) {
        if (used[i]) continue;
        // equal values are placed in order, which avoids duplicate permutations
        if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
        used[i] = true;
        current.push_back(nums[i]);
        collectPermutations(nums, used, current, result);
        current.pop_back();
        used[i] = false;
    }
}

class Solution {
public:
    vector<vector<int>> permuteUnique(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        vector<bool> used(nums.size(), false);
        vector<int> current;
        vector<vector<int>> result;
        collectPermutations(nums, used, current, result);
        return result;
    }
};

// Approach: Stack of operands; each operator combines the top two values.
// Time O(n), Space O(n)
class Solution {
public:
    int evalRPN(vector<string>& tokens) {
        stack<long long> operands;
        for (const string& token : tokens) {
            if (token == "+" || token == "-" || token == "*" || token == "/") {
                long long right = operands.top();
                operands.pop();
                long long left = operands.top();
                operands.pop();
                if (token == "+") {
                    operands.push(left + right);
                } else if (token == "-") {
                    operands.push(left - right);
                } else if (token == "*") {
                    operands.push(left * right);
                } else {
                    operands.push(left / right);
                }
            } else {
                operands.push(stoll(token));
            }
        }
        return operands.top();
    }
};

// Approach: Mark each seen value v by negating nums[v - 1]; the positive slots are the missing numbers.
// Time O(n), Space O(1) extra (excluding output)
class Solution {
public:
    vector<int> findDisappearedNumbers(vector<int>& nums) {
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            int index = abs(nums[i]) - 1;
            if (nums[index] > 0) nums[index] = -nums[index];
        }
        vector<int> missing;
        for (int i = 0; i < n; i++) {
            if (nums[i] > 0) missing.push_back(i + 1);
        }
        return missing;
    }
};

// Approach: Binary search comparing the middle with the right end to find the rotation point.
// Time O(log n), Space O(1)
class Solution {
public:
    int findMin(vector<int>& nums) {
        int low = 0;
        int high = nums.size() - 1;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] > nums[high]) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return nums[low];
    }
};

// Approach: Cyclic sort that puts each value v in 1..n at index v - 1, then find the first misplaced slot.
// Time O(n), Space O(1)
class Solution {
public:
    int firstMissingPositive(vector<int>& nums) {
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {
                swap(nums[i], nums[nums[i] - 1]);
            }
        }
        for (int i = 0; i < n; i++) {
            if (nums[i] != i + 1) return i + 1;
        }
        return n + 1;
    }
};

// Approach: Greedy single pass; if the tank goes negative, restart from the next station.
// Time O(n), Space O(1)
class Solution {
public:
    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {
        int n = gas.size();
        int totalGain = 0;
        int tank = 0;
        int start = 0;
        for (int i = 0; i < n; i++) {
            int gain = gas[i] - cost[i];
            totalGain += gain;
            tank += gain;
            if (tank < 0) {
                start = i + 1;
                tank = 0;
            }
        }
        return totalGain < 0 ? -1 : start;
    }
};

// Approach: XOR the numbers and count set bits by repeatedly clearing the lowest one.
// Time O(number of set bits) which is at most O(32), Space O(1)
class Solution {
public:
    int hammingDistance(int x, int y) {
        unsigned int diff = (unsigned int)x ^ (unsigned int)y;
        int count = 0;
        while (diff) {
            diff &= diff - 1;  // clear the lowest set bit
            count++;
        }
        return count;
    }
};

// Approach: Houses are circular, so take the better of robbing without the last or without the first house.
// Time O(n), Space O(1)
int robLinear(const vector<int>& nums, int begin, int end) {
    int robbed = 0;
    int skipped = 0;
    for (int i = begin; i < end; i++) {
        int robbedNow = skipped + nums[i];
        skipped = max(robbed, skipped);
        robbed = robbedNow;
    }
    return max(robbed, skipped);
}

class Solution {
public:
    int rob(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return nums[0];
        return max(robLinear(nums, 0, n - 1), robLinear(nums, 1, n));
    }
};

// Approach: The product is maximised by splitting into as many 3s as possible, using a 4 or 2 for the remainder.
// Time O(n), Space O(1)
class Solution {
public:
    int integerBreak(int n) {
        if (n <= 3) return n - 1;
        int threes = n / 3;
        int remainder = n % 3;
        if (remainder == 1) threes--;  // 3 + 1 is worse than 2 + 2
        long long product = 1;
        for (int i = 0; i < threes; i++) product *= 3;
        if (remainder == 1) return product * 4;
        if (remainder == 2) return product * 2;
        return product;
    }
};

// Approach: Recursively invert both subtrees, then swap them.
// Time O(n), Space O(h) where h is the tree height
class Solution {
public:
    TreeNode* invertTree(TreeNode* root) {
        if (!root) return nullptr;
        TreeNode* invertedLeft = invertTree(root->left);
        TreeNode* invertedRight = invertTree(root->right);
        root->left = invertedRight;
        root->right = invertedLeft;
        return root;
    }
};

// Approach: Each land cell adds 4 edges, minus 2 for every shared edge with the cell above or to the left.
// Time O(m * n), Space O(1)
class Solution {
public:
    int islandPerimeter(vector<vector<int>>& grid) {
        int rows = grid.size();
        int cols = grid[0].size();
        int perimeter = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != 1) continue;
                perimeter += 4;
                if (r > 0 && grid[r - 1][c] == 1) perimeter -= 2;
                if (c > 0 && grid[r][c - 1] == 1) perimeter -= 2;
            }
        }
        return perimeter;
    }
};

// Approach: Greedy BFS by levels; extend the farthest reach and jump when the current range ends.
// Time O(n), Space O(1)
class Solution {
public:
    int jump(vector<int>& nums) {
        int n = nums.size();
        int jumps = 0;
        int currentEnd = 0;
        int farthest = 0;
        for (int i = 0; i + 1 < n; i++) {
            farthest = max(farthest, i + nums[i]);
            if (i == currentEnd) {
                jumps++;
                currentEnd = farthest;
            }
        }
        return jumps;
    }
};

// Approach: Iterative inorder traversal visits values in sorted order; stop at the k-th.
// Time O(h + k), Space O(h) where h is the tree height
class Solution {
public:
    int kthSmallest(TreeNode* root, int k) {
        vector<TreeNode*> stack;
        TreeNode* node = root;
        while (node || !stack.empty()) {
            while (node) {
                stack.push_back(node);
                node = node->left;
            }
            node = stack.back();
            stack.pop_back();
            if (--k == 0) return node->val;
            node = node->right;
        }
        return -1;
    }
};

// Approach: Max-heap; repeatedly smash the two heaviest stones and push back the difference.
// Time O(n log n), Space O(n)
class Solution {
public:
    int lastStoneWeight(vector<int>& stones) {
        priority_queue<int> heap(stones.begin(), stones.end());
        while (heap.size() > 1) {
            int heaviest = heap.top();
            heap.pop();
            int second = heap.top();
            heap.pop();
            if (heaviest != second) heap.push(heaviest - second);
        }
        return heap.empty() ? 0 : heap.top();
    }
};

// Approach: 2D DP where dp[i][j] is the LCS length of the first i and first j characters.
// Time O(n * m), Space O(n * m)
class Solution {
public:
    int longestCommonSubsequence(string text1, string text2) {
        int n = text1.size();
        int m = text2.size();
        vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (text1[i - 1] == text2[j - 1]) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }
        return dp[n][m];
    }
};

// Approach: Expand around each of the 2n-1 palindrome centers and keep the longest.
// Time O(n^2), Space O(1)
class Solution {
public:
    string longestPalindrome(string s) {
        int n = s.size();
        int bestLength = 0;
        int bestStart = 0;
        for (int center = 0; center < 2 * n - 1; center++) {
            // Even centers start with left == right - 1, odd centers with left == right.
            int left = center / 2;
            int right = left + center % 2;
            while (left >= 0 && right < n && s[left] == s[right]) {
                left--;
                right++;
            }
            int length = right - left - 1;
            if (length > bestLength) {
                bestLength = length;
                bestStart = left + 1;
            }
        }
        return s.substr(bestStart, bestLength);
    }
};

// Approach: Sliding window storing the last index of each byte; jump the window start past a repeat.
// Time O(n), Space O(1) (fixed 256-entry table)
class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int n = s.size();
        vector<int> lastSeenAt(256, -1);
        int bestLength = 0;
        int windowStart = 0;
        for (int i = 0; i < n; i++) {
            unsigned char ch = s[i];
            if (lastSeenAt[ch] >= windowStart) windowStart = lastSeenAt[ch] + 1;
            lastSeenAt[ch] = i;
            bestLength = max(bestLength, i - windowStart + 1);
        }
        return bestLength;
    }
};

// Approach: Recursive DFS; the LCA is where both subtrees report a target node.
// Time O(n), Space O(h)
class Solution {
public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        if (!root || root == p || root == q) {
            return root;
        }
        TreeNode* left = lowestCommonAncestor(root->left, p, q);
        TreeNode* right = lowestCommonAncestor(root->right, p, q);
        if (left && right) {
            return root;
        }
        return left ? left : right;
    }
};

// Approach: Build column heights row by row and solve largest-rectangle-in-histogram with a monotonic stack.
// Time O(rows * cols), Space O(cols)
class Solution {
public:
    int maximalRectangle(vector<vector<int>>& matrix) {
        if (matrix.empty()) return 0;
        int cols = matrix[0].size();
        int bestArea = 0;
        vector<int> heights(cols, 0);
        for (const auto& row : matrix) {
            for (int j = 0; j < cols; j++) {
                heights[j] = row[j] == 1 ? heights[j] + 1 : 0;
            }
            vector<int> stack;  // indices with strictly increasing heights
            for (int j = 0; j <= cols; j++) {
                int current = j < cols ? heights[j] : 0;
                while (!stack.empty() && heights[stack.back()] >= current) {
                    int height = heights[stack.back()];
                    stack.pop_back();
                    int leftEdge = stack.empty() ? -1 : stack.back();
                    bestArea = max(bestArea, height * (j - leftEdge - 1));
                }
                stack.push_back(j);
            }
        }
        return bestArea;
    }
};

// Approach: Track the max and min product ending at each index, since a negative can flip them.
// Time O(n), Space O(1)
class Solution {
public:
    int maxProduct(vector<int>& nums) {
        long long best = nums[0];
        long long maxEnding = nums[0];
        long long minEnding = nums[0];
        for (int i = 1; i < (int)nums.size(); i++) {
            long long value = nums[i];
            long long candidateA = maxEnding * value;
            long long candidateB = minEnding * value;
            maxEnding = max({value, candidateA, candidateB});
            minEnding = min({value, candidateA, candidateB});
            best = max(best, maxEnding);
        }
        return best;
    }
};

// Approach: Find the middle with fast/slow pointers, reverse the second half, then sum paired nodes.
// Time O(n), Space O(1)
class Solution {
public:
    int pairSum(ListNode* head) {
        ListNode* slow = head;
        ListNode* fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        ListNode* reversed = nullptr;
        while (slow) {
            ListNode* next = slow->next;
            slow->next = reversed;
            reversed = slow;
            slow = next;
        }
        int bestSum = 0;
        ListNode* front = head;
        for (ListNode* back = reversed; back; back = back->next) {
            bestSum = max(bestSum, front->val + back->val);
            front = front->next;
        }
        return bestSum;
    }
};

// Approach: Merge from the back with three pointers so nums1 is filled without overwriting unread values.
// Time O(m + n), Space O(1)
class Solution {
public:
    void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
        int i = m - 1;
        int j = n - 1;
        int write = m + n - 1;
        while (j >= 0) {
            if (i >= 0 && nums1[i] > nums2[j]) {
                nums1[write--] = nums1[i--];
            } else {
                nums1[write--] = nums2[j--];
            }
        }
    }
};

// Approach: DP keeping the cheapest cost to reach each of the previous two steps.
// Time O(n), Space O(1)
class Solution {
public:
    int minCostClimbingStairs(vector<int>& cost) {
        int n = cost.size();
        int costTwoBack = 0;
        int costOneBack = 0;
        for (int step = 2; step <= n; step++) {
            int current = min(costOneBack + cost[step - 1], costTwoBack + cost[step - 2]);
            costTwoBack = costOneBack;
            costOneBack = current;
        }
        return costOneBack;
    }
};

// Approach: Recursive DFS that only counts a path when it ends at a leaf.
// Time O(n), Space O(h) where h is the tree height
class Solution {
public:
    int minDepth(TreeNode* root) {
        if (!root) return 0;
        // a node with one child is not a leaf, so follow only the side that exists
        if (!root->left) return 1 + minDepth(root->right);
        if (!root->right) return 1 + minDepth(root->left);
        return 1 + min(minDepth(root->left), minDepth(root->right));
    }
};

// Approach: DP over a single row where each cell takes the cheaper of the cell above or to the left.
// Time O(m * n), Space O(n)
class Solution {
public:
    int minPathSum(vector<vector<int>>& grid) {
        int cols = grid[0].size();
        vector<int> minCost(cols, INT_MAX / 2);
        minCost[0] = 0;
        for (const auto& row : grid) {
            for (int j = 0; j < cols; j++) {
                if (j > 0) minCost[j] = min(minCost[j], minCost[j - 1]);
                minCost[j] += row[j];
            }
        }
        return minCost[cols - 1];
    }
};

// Approach: XOR all indices and values with n; paired numbers cancel and the missing one remains.
// Time O(n), Space O(1)
class Solution {
public:
    int missingNumber(vector<int>& nums) {
        int n = nums.size();
        int missing = n;
        for (int i = 0; i < n; i++) {
            missing ^= i ^ nums[i];
        }
        return missing;
    }
};

// Approach: Dijkstra from the source with a min-heap; the answer is the largest shortest distance.
// Time O(E log V), Space O(V + E)
class Solution {
public:
    int networkDelayTime(vector<vector<int>>& times, int n, int k) {
        vector<vector<pair<int, int>>> graph(n + 1);  // node -> (neighbor, weight)
        for (const auto& edge : times) {
            graph[edge[0]].push_back({edge[1], edge[2]});
        }
        vector<int> dist(n + 1, INT_MAX);
        dist[k] = 0;
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> heap;
        heap.push({0, k});
        while (!heap.empty()) {
            auto [d, node] = heap.top();
            heap.pop();
            if (d > dist[node]) continue;
            for (const auto& [next, weight] : graph[node]) {
                if (d + weight < dist[next]) {
                    dist[next] = d + weight;
                    heap.push({dist[next], next});
                }
            }
        }
        int longest = 0;
        for (int node = 1; node <= n; node++) {
            longest = max(longest, dist[node]);
        }
        return longest == INT_MAX ? -1 : longest;
    }
};

// Approach: Sort by end time and greedily keep each interval that starts after the last kept one ends.
// Time O(n log n), Space O(1) extra
class Solution {
public:
    int eraseOverlapIntervals(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end(),
             [](const vector<int>& a, const vector<int>& b) { return a[1] < b[1]; });
        int removed = 0;
        int lastEnd = INT_MIN;
        for (const auto& interval : intervals) {
            if (interval[0] >= lastEnd) {
                lastEnd = interval[1];
            } else {
                removed++;
            }
        }
        return removed;
    }
};

// Approach: Scan the grid and flood-fill each unvisited land cell with an explicit stack, counting fills.
// Time O(rows * cols), Space O(rows * cols)
class Solution {
public:
    int numIslands(vector<vector<char>>& grid) {
        int rows = grid.size();
        int cols = rows ? grid[0].size() : 0;
        int islands = 0;
        const int rowStep[4] = {1, -1, 0, 0};
        const int colStep[4] = {0, 0, 1, -1};
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '1') continue;
                islands++;
                grid[r][c] = '0';  // sinking a cell marks it visited
                vector<pair<int, int>> stack = {{r, c}};
                while (!stack.empty()) {
                    auto [row, col] = stack.back();
                    stack.pop_back();
                    for (int d = 0; d < 4; d++) {
                        int nextRow = row + rowStep[d];
                        int nextCol = col + colStep[d];
                        bool inside = nextRow >= 0 && nextRow < rows && nextCol >= 0 &&
                                      nextCol < cols;
                        if (inside && grid[nextRow][nextCol] == '1') {
                            grid[nextRow][nextCol] = '0';
                            stack.push_back({nextRow, nextCol});
                        }
                    }
                }
            }
        }
        return islands;
    }
};

// Approach: Find the middle, reverse the second half, and compare it with the first half.
// Time O(n), Space O(1)
class Solution {
public:
    bool isPalindrome(ListNode* head) {
        ListNode* slow = head;
        ListNode* fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        ListNode* reversed = nullptr;
        while (slow) {
            ListNode* next = slow->next;
            slow->next = reversed;
            reversed = slow;
            slow = next;
        }
        ListNode* front = head;
        for (ListNode* back = reversed; back; back = back->next) {
            if (front->val != back->val) return false;
            front = front->next;
        }
        return true;
    }
};

// Approach: Expand around each of the 2n - 1 centers (characters and gaps), counting every palindrome found.
// Time O(n^2), Space O(1)
class Solution {
public:
    int countSubstrings(string s) {
        int n = s.size();
        int count = 0;
        for (int center = 0; center < 2 * n - 1; center++) {
            int left = center / 2;
            int right = left + center % 2;
            while (left >= 0 && right < n && s[left] == s[right]) {
                count++;
                left--;
                right++;
            }
        }
        return count;
    }
};

// Approach: Split nodes into a "less than x" list and a "greater or equal" list, then join them.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* partition(ListNode* head, int x) {
        ListNode smallHead(0);
        ListNode largeHead(0);
        ListNode* smallTail = &smallHead;
        ListNode* largeTail = &largeHead;
        for (ListNode* node = head; node; node = node->next) {
            if (node->val < x) {
                smallTail->next = node;
                smallTail = node;
            } else {
                largeTail->next = node;
                largeTail = node;
            }
        }
        largeTail->next = nullptr;
        smallTail->next = largeHead.next;
        return smallHead.next;
    }
};

// Approach: DFS with prefix sums; count earlier prefixes on the current path equal to sum - target.
// Time O(n), Space O(n)
int countPaths(TreeNode* node, long long pathSum, int target,
               unordered_map<long long, int>& prefixCounts) {
    if (!node) return 0;
    pathSum += node->val;
    int paths = 0;
    auto it = prefixCounts.find(pathSum - target);
    if (it != prefixCounts.end()) paths = it->second;
    prefixCounts[pathSum]++;
    paths += countPaths(node->left, pathSum, target, prefixCounts);
    paths += countPaths(node->right, pathSum, target, prefixCounts);
    prefixCounts[pathSum]--;  // leaving this node: it is no longer on the path
    return paths;
}

class Solution {
public:
    int pathSum(TreeNode* root, int targetSum) {
        unordered_map<long long, int> prefixCounts;
        prefixCounts[0] = 1;
        return countPaths(root, 0, targetSum, prefixCounts);
    }
};

// Approach: Slide a window of length |s1| over s2 and compare letter counts with those of s1.
// Time O(m), Space O(1)
class Solution {
public:
    bool checkInclusion(string s1, string s2) {
        int n = s1.size();
        int m = s2.size();
        if (n > m) return false;
        vector<int> needed(26, 0);
        vector<int> window(26, 0);
        for (int i = 0; i < n; i++) {
            needed[s1[i] - 'a']++;
            window[s2[i] - 'a']++;
        }
        if (needed == window) return true;
        for (int i = n; i < m; i++) {
            window[s2[i] - 'a']++;
            window[s2[i - n] - 'a']--;
            if (needed == window) return true;
        }
        return false;
    }
};

// Approach: Fill each slot with the product of everything to its left, then multiply by everything to its right.
// Time O(n), Space O(1) extra (excluding output)
class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        int n = nums.size();
        vector<int> result(n, 1);
        long long prefix = 1;
        for (int i = 0; i < n; i++) {
            result[i] = prefix;
            prefix *= nums[i];
        }
        long long suffix = 1;
        for (int i = n - 1; i >= 0; i--) {
            result[i] = result[i] * suffix;
            suffix *= nums[i];
        }
        return result;
    }
};

// Approach: Two pointers; copy each value that differs from the last kept one.
// Time O(n), Space O(1)
class Solution {
public:
    int removeDuplicates(vector<int>& nums) {
        if (nums.empty()) {
            return 0;
        }
        int size = nums.size();
        int kept = 1;
        for (int i = 1; i < size; i++) {
            if (nums[i] != nums[kept - 1]) {
                nums[kept] = nums[i];
                kept++;
            }
        }
        return kept;
    }
};

// Approach: Walk the list with a dummy head and unlink every node holding the target value.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* removeElements(ListNode* head, int val) {
        ListNode dummy(0);
        dummy.next = head;
        ListNode* current = &dummy;
        while (current->next) {
            if (current->next->val == val) {
                current->next = current->next->next;
            } else {
                current = current->next;
            }
        }
        return dummy.next;
    }
};

// Approach: s is a repeated pattern exactly when it occurs inside s + s with the first and last characters removed.
// Time O(n^2) worst case (std::string::find), Space O(n)
class Solution {
public:
    bool repeatedSubstringPattern(string s) {
        string doubled = s + s;
        return doubled.substr(1, doubled.size() - 2).find(s) != string::npos;
    }
};

// Approach: Walk to the node before the segment, then repeatedly move the next node to the segment front.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* reverseBetween(ListNode* head, int left, int right) {
        ListNode dummy(0);
        dummy.next = head;
        ListNode* beforeSegment = &dummy;
        for (int i = 0; i < left - 1; i++) {
            beforeSegment = beforeSegment->next;
        }
        ListNode* segmentTail = beforeSegment->next;
        // move the node after segmentTail to the front of the segment, right - left times
        for (int i = 0; i < right - left; i++) {
            ListNode* moving = segmentTail->next;
            segmentTail->next = moving->next;
            moving->next = beforeSegment->next;
            beforeSegment->next = moving;
        }
        return dummy.next;
    }
};

// Approach: Rotate right by k using three reversals: whole array, first k, then the rest.
// Time O(n), Space O(1)
class Solution {
public:
    void rotate(vector<int>& nums, int k) {
        int n = nums.size();
        if (n == 0) return;
        k %= n;
        reverse(nums.begin(), nums.end());
        reverse(nums.begin(), nums.begin() + k);
        reverse(nums.begin() + k, nums.end());
    }
};

// Approach: Multi-source BFS from all rotten oranges, one level per minute, tracking fresh oranges left.
// Time O(rows * cols), Space O(rows * cols)
class Solution {
public:
    int orangesRotting(vector<vector<int>>& grid) {
        int rows = grid.size();
        int cols = grid[0].size();
        int fresh = 0;
        int minutes = 0;
        queue<pair<int, int>> queue;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 2) {
                    queue.push({r, c});
                } else if (grid[r][c] == 1) {
                    fresh++;
                }
            }
        }
        const int rowStep[4] = {1, -1, 0, 0};
        const int colStep[4] = {0, 0, 1, -1};
        while (!queue.empty() && fresh > 0) {
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                auto [row, col] = queue.front();
                queue.pop();
                for (int d = 0; d < 4; d++) {
                    int nextRow = row + rowStep[d];
                    int nextCol = col + colStep[d];
                    bool inside = nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols;
                    if (inside && grid[nextRow][nextCol] == 1) {
                        grid[nextRow][nextCol] = 2;
                        fresh--;
                        queue.push({nextRow, nextCol});
                    }
                }
            }
            minutes++;
        }
        return fresh == 0 ? minutes : -1;
    }
};

// Approach: Binary search; at each step one half is sorted, so check whether the target lies in it.
// Time O(log n), Space O(1)
class Solution {
public:
    int search(vector<int>& nums, int target) {
        int low = 0;
        int high = nums.size() - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] == target) return mid;
            if (nums[low] <= nums[mid]) {
                // left half is sorted
                if (nums[low] <= target && target < nums[mid]) {
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            } else {
                // right half is sorted
                if (nums[mid] < target && target <= nums[high]) {
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
        }
        return -1;
    }
};

// Approach: BFS over 8-directional moves through zero cells, storing the path length in each visited cell.
// Time O(n^2), Space O(n^2)
class Solution {
public:
    int shortestPathBinaryMatrix(vector<vector<int>>& grid) {
        int n = grid.size();
        if (grid[0][0] == 1 || grid[n - 1][n - 1] == 1) return -1;
        vector<vector<int>> pathLength(n, vector<int>(n, 0));  // 0 means not visited
        pathLength[0][0] = 1;
        queue<pair<int, int>> queue;
        queue.push({0, 0});
        while (!queue.empty()) {
            auto [row, col] = queue.front();
            queue.pop();
            if (row == n - 1 && col == n - 1) return pathLength[row][col];
            for (int dRow = -1; dRow <= 1; dRow++) {
                for (int dCol = -1; dCol <= 1; dCol++) {
                    int nextRow = row + dRow;
                    int nextCol = col + dCol;
                    bool inside = nextRow >= 0 && nextRow < n && nextCol >= 0 && nextCol < n;
                    bool open = inside && grid[nextRow][nextCol] == 0;
                    if (open && pathLength[nextRow][nextCol] == 0) {
                        pathLength[nextRow][nextCol] = pathLength[row][col] + 1;
                        queue.push({nextRow, nextCol});
                    }
                }
            }
        }
        return -1;
    }
};

// Approach: Monotonic deque of indices whose values decrease, so the front is always the window maximum.
// Time O(n), Space O(k)
class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        int n = nums.size();
        deque<int> window;  // indices with decreasing values from front to back
        vector<int> result;
        for (int i = 0; i < n; i++) {
            while (!window.empty() && nums[window.back()] <= nums[i]) window.pop_back();
            window.push_back(i);
            if (window.front() <= i - k) window.pop_front();
            if (i >= k - 1) result.push_back(nums[window.front()]);
        }
        return result;
    }
};

// Approach: Walk the border layer by layer, shrinking the top, bottom, left and right bounds.
// Time O(m * n), Space O(1) extra (excluding output)
class Solution {
public:
    vector<int> spiralOrder(vector<vector<int>>& matrix) {
        vector<int> result;
        if (matrix.empty()) return result;
        int top = 0;
        int bottom = matrix.size() - 1;
        int left = 0;
        int right = matrix[0].size() - 1;
        while (top <= bottom && left <= right) {
            for (int j = left; j <= right; j++) result.push_back(matrix[top][j]);
            for (int i = top + 1; i <= bottom; i++) result.push_back(matrix[i][right]);
            // the last two sides only exist when the layer has more than one row and column
            if (top < bottom && left < right) {
                for (int j = right - 1; j >= left; j--) result.push_back(matrix[bottom][j]);
                for (int i = bottom - 1; i > top; i--) result.push_back(matrix[i][left]);
            }
            top++;
            bottom--;
            left++;
            right--;
        }
        return result;
    }
};

// Approach: Two pointers from both ends; the larger absolute value gives the largest square, filled from the back.
// Time O(n), Space O(n)
class Solution {
public:
    vector<int> sortedSquares(vector<int>& nums) {
        int n = nums.size();
        vector<int> result(n);
        int left = 0;
        int right = n - 1;
        for (int i = n - 1; i >= 0; i--) {
            if (abs(nums[left]) > abs(nums[right])) {
                result[i] = nums[left] * nums[left];
                left++;
            } else {
                result[i] = nums[right] * nums[right];
                right--;
            }
        }
        return result;
    }
};

// Approach: Monotonic stacks give how far each element is the minimum on each side; add value * left * right.
// Time O(n), Space O(n)
class Solution {
public:
    int sumSubarrayMins(vector<int>& arr) {
        const long long MOD = 1000000007LL;
        int n = arr.size();
        vector<int> leftSpan(n);
        vector<int> rightSpan(n);
        vector<int> stack;
        for (int i = 0; i < n; i++) {
            while (!stack.empty() && arr[stack.back()] > arr[i]) stack.pop_back();
            leftSpan[i] = i - (stack.empty() ? -1 : stack.back());
            stack.push_back(i);
        }
        stack.clear();
        // strict on the left and non-strict on the right so equal values are counted once
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.empty() && arr[stack.back()] >= arr[i]) stack.pop_back();
            rightSpan[i] = (stack.empty() ? n : stack.back()) - i;
            stack.push_back(i);
        }
        long long total = 0;
        for (int i = 0; i < n; i++) {
            long long contribution = (long long)arr[i] * leftSpan[i] % MOD * rightSpan[i];
            total = (total + contribution) % MOD;
        }
        return total;
    }
};

// Approach: Mark 'O' cells reachable from the border as safe, then flip the rest.
// Time O(m*n), Space O(m*n)
class Solution {
public:
    void solve(vector<vector<char>>& board) {
        int m = board.size();
        if (m == 0) {
            return;
        }
        int n = board[0].size();
        for (int i = 0; i < m; i++) {
            markSafe(board, i, 0);
            markSafe(board, i, n - 1);
        }
        for (int j = 0; j < n; j++) {
            markSafe(board, 0, j);
            markSafe(board, m - 1, j);
        }
        // 'T' cells are border-connected and stay 'O'; every other cell becomes 'X'.
        for (auto& row : board) {
            for (char& cell : row) {
                cell = (cell == 'T') ? 'O' : 'X';
            }
        }
    }

private:
    void markSafe(vector<vector<char>>& board, int r, int c) {
        int rows = board.size();
        int cols = board[0].size();
        if (r < 0 || c < 0 || r >= rows || c >= cols || board[r][c] != 'O') {
            return;
        }
        board[r][c] = 'T';
        markSafe(board, r + 1, c);
        markSafe(board, r - 1, c);
        markSafe(board, r, c + 1);
        markSafe(board, r, c - 1);
    }
};

// Approach: Recursively check that two subtrees are mirror images of each other.
// Time O(n), Space O(h) where h is the tree height
bool isMirror(TreeNode* first, TreeNode* second) {
    if (!first && !second) return true;
    if (!first || !second || first->val != second->val) return false;
    return isMirror(first->left, second->right) && isMirror(first->right, second->left);
}

class Solution {
public:
    bool isSymmetric(TreeNode* root) {
        return isMirror(root, root);
    }
};

// Approach: Count frequencies, sort distinct values by count (ties by value), keep the first k.
// Time O(n + d log d) where d is the number of distinct values, Space O(d)
class Solution {
public:
    vector<int> topKFrequent(vector<int>& nums, int k) {
        unordered_map<int, int> frequency;
        for (int value : nums) frequency[value]++;
        vector<int> values;
        for (const auto& entry : frequency) values.push_back(entry.first);
        sort(values.begin(), values.end(), [&](int a, int b) {
            if (frequency[a] != frequency[b]) return frequency[a] > frequency[b];
            return a < b;
        });
        values.resize(k);
        return values;
    }
};

// Approach: Two pointers from both ends of the sorted array, moving the one that brings the sum closer.
// Time O(n), Space O(1)
class Solution {
public:
    vector<int> twoSum(vector<int>& numbers, int target) {
        int low = 0;
        int high = numbers.size() - 1;
        while (low < high) {
            long long sum = (long long)numbers[low] + numbers[high];
            if (sum == target) return {low + 1, high + 1};
            if (sum < target) {
                low++;
            } else {
                high--;
            }
        }
        return {};
    }
};

// Approach: Row-by-row DP where ways[j] adds the paths from the left, and obstacles reset a cell to zero.
// Time O(m * n), Space O(n)
class Solution {
public:
    int uniquePathsWithObstacles(vector<vector<int>>& grid) {
        int cols = grid[0].size();
        vector<long long> ways(cols, 0);
        ways[0] = 1;
        for (const auto& row : grid) {
            for (int j = 0; j < cols; j++) {
                if (row[j] == 1) {
                    ways[j] = 0;
                } else if (j > 0) {
                    ways[j] += ways[j - 1];
                }
            }
        }
        return ways[cols - 1];
    }
};

// Approach: Two pointers inward; on the first mismatch, try skipping either character and check the rest.
// Time O(n), Space O(1)
bool isPalindromeRange(const string& s, int left, int right) {
    while (left < right) {
        if (s[left] != s[right]) return false;
        left++;
        right--;
    }
    return true;
}

class Solution {
public:
    bool validPalindrome(string s) {
        int left = 0;
        int right = s.size() - 1;
        while (left < right) {
            if (s[left] != s[right]) {
                return isPalindromeRange(s, left + 1, right) ||
                       isPalindromeRange(s, left, right - 1);
            }
            left++;
            right--;
        }
        return true;
    }
};

// Approach: DFS passing down the open interval (low, high) every node value must fall inside.
// Time O(n), Space O(h) where h is the tree height
bool isWithinBounds(TreeNode* node, long long low, long long high) {
    if (!node) return true;
    if (node->val <= low || node->val >= high) return false;
    return isWithinBounds(node->left, low, node->val) &&
           isWithinBounds(node->right, node->val, high);
}

class Solution {
public:
    bool isValidBST(TreeNode* root) {
        return isWithinBounds(root, LLONG_MIN, LLONG_MAX);
    }
};

// Approach: DFS backtracking from every cell, marking cells on the current path as visited.
// Time O(m * n * 3^L) where L is the word length, Space O(L)
bool matchFrom(vector<vector<char>>& board, vector<vector<bool>>& visited, const string& word,
               int row, int col, int index) {
    if (board[row][col] != word[index]) return false;
    if (index == (int)word.size() - 1) return true;
    int rows = board.size();
    int cols = board[0].size();
    const int rowStep[4] = {1, -1, 0, 0};
    const int colStep[4] = {0, 0, 1, -1};
    visited[row][col] = true;
    bool found = false;
    for (int d = 0; d < 4 && !found; d++) {
        int nextRow = row + rowStep[d];
        int nextCol = col + colStep[d];
        bool inside = nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols;
        if (inside && !visited[nextRow][nextCol]) {
            found = matchFrom(board, visited, word, nextRow, nextCol, index + 1);
        }
    }
    visited[row][col] = false;
    return found;
}

class Solution {
public:
    bool exist(vector<vector<char>>& board, string word) {
        int rows = board.size();
        int cols = board[0].size();
        vector<vector<bool>> visited(rows, vector<bool>(cols, false));
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (matchFrom(board, visited, word, r, c, 0)) return true;
            }
        }
        return false;
    }
};

// Approach: Sort, fix one number and move two pointers inward to home in on the target.
// Time O(n^2), Space O(1)
class Solution {
public:
    int threeSumClosest(vector<int>& nums, int target) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int closest = nums[0] + nums[1] + nums[2];
        for (int i = 0; i < n - 2; i++) {
            int left = i + 1;
            int right = n - 1;
            while (left < right) {
                int sum = nums[i] + nums[left] + nums[right];
                if (abs(sum - target) < abs(closest - target)) {
                    closest = sum;
                }
                if (sum < target) {
                    left++;
                } else if (sum > target) {
                    right--;
                } else {
                    return sum;
                }
            }
        }
        return closest;
    }
};

// Approach: Walk both lists digit by digit, carrying overflow into the next node.
// Time O(max(n, m)), Space O(1) extra besides the output list
class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        ListNode dummy(0);
        ListNode* tail = &dummy;
        int carry = 0;
        while (l1 || l2 || carry) {
            int sum = carry;
            if (l1) {
                sum += l1->val;
                l1 = l1->next;
            }
            if (l2) {
                sum += l2->val;
                l2 = l2->next;
            }
            carry = sum / 10;
            tail->next = new ListNode(sum % 10);
            tail = tail->next;
        }
        return dummy.next;
    }
};

// Approach: Track the lowest price so far and the best profit from selling today.
// Time O(n), Space O(1)
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int bestProfit = 0;
        int lowestPrice = INT_MAX;
        for (int price : prices) {
            lowestPrice = min(lowestPrice, price);
            bestProfit = max(bestProfit, price - lowestPrice);
        }
        return bestProfit;
    }
};

// Approach: State machine DP over holding, just-sold and resting states.
// Time O(n), Space O(1)
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int holding = INT_MIN / 2;
        int justSold = 0;  // cooldown applies tomorrow
        int resting = 0;   // free to buy
        for (int price : prices) {
            int newHolding = max(holding, resting - price);
            int newJustSold = holding + price;
            resting = max(resting, justSold);
            holding = newHolding;
            justSold = newJustSold;
        }
        return max(justSold, resting);
    }
};

// Approach: Breadth-first search, processing the queue one level at a time.
// Time O(n), Space O(n)
class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        vector<vector<int>> result;
        if (!root) {
            return result;
        }
        queue<TreeNode*> queue;
        queue.push(root);
        while (!queue.empty()) {
            vector<int> level;
            for (int remaining = queue.size(); remaining > 0; remaining--) {
                TreeNode* node = queue.front();
                queue.pop();
                level.push_back(node->val);
                if (node->left) {
                    queue.push(node->left);
                }
                if (node->right) {
                    queue.push(node->right);
                }
            }
            result.push_back(level);
        }
        return result;
    }
};

// Approach: Level-order traversal, reversing every other level's values.
// Time O(n), Space O(n)
class Solution {
public:
    vector<vector<int>> zigzagLevelOrder(TreeNode* root) {
        vector<vector<int>> result;
        if (!root) {
            return result;
        }
        vector<TreeNode*> level = {root};
        bool leftToRight = true;
        while (!level.empty()) {
            vector<int> values;
            vector<TreeNode*> nextLevel;
            for (TreeNode* node : level) {
                values.push_back(node->val);
                if (node->left) {
                    nextLevel.push_back(node->left);
                }
                if (node->right) {
                    nextLevel.push_back(node->right);
                }
            }
            if (!leftToRight) {
                reverse(values.begin(), values.end());
            }
            result.push_back(values);
            leftToRight = !leftToRight;
            level = nextLevel;
        }
        return result;
    }
};

// Approach: Greedily plant in every empty plot whose neighbours are both empty.
// Time O(m), Space O(1)
class Solution {
public:
    bool canPlaceFlowers(vector<int>& flowerbed, int n) {
        int planted = 0;
        int m = flowerbed.size();
        for (int i = 0; i < m; i++) {
            if (flowerbed[i] != 0) {
                continue;
            }
            bool leftEmpty = i == 0 || flowerbed[i - 1] == 0;
            bool rightEmpty = i == m - 1 || flowerbed[i + 1] == 0;
            if (leftEmpty && rightEmpty) {
                flowerbed[i] = 1;
                planted++;
            }
        }
        return planted >= n;
    }
};

// Approach: Sort cars by position from the target backwards; a later arrival starts a new fleet.
// Time O(n log n), Space O(n)
class Solution {
public:
    int carFleet(int target, vector<int>& position, vector<int>& speed) {
        int n = position.size();
        vector<int> order(n);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) {
            return position[a] > position[b];
        });

        int fleets = 0;
        // Distance and speed of the fleet ahead; times are compared by cross-multiplying.
        long long aheadDistance = 0;
        long long aheadSpeed = 1;
        for (int car : order) {
            long long distance = target - position[car];
            long long carSpeed = speed[car];
            if (distance * aheadSpeed > aheadDistance * carSpeed) {
                fleets++;
                aheadDistance = distance;
                aheadSpeed = carSpeed;
            }
        }
        return fleets;
    }
};

// Approach: Bottom-up DP where dp[a] is the fewest coins that make amount a.
// Time O(amount * k), Space O(amount)
class Solution {
public:
    int coinChange(vector<int>& coins, int amount) {
        int unreachable = amount + 1;
        vector<int> dp(amount + 1, unreachable);
        dp[0] = 0;
        for (int a = 1; a <= amount; a++) {
            for (int coin : coins) {
                if (coin <= a) {
                    dp[a] = min(dp[a], dp[a - coin] + 1);
                }
            }
        }
        return dp[amount] == unreachable ? -1 : dp[amount];
    }
};

// Approach: The next preorder value is the root; its inorder index splits left and right subtrees.
// Time O(n), Space O(n)
TreeNode* buildSubtree(const vector<int>& preorder, int& next,
                       unordered_map<int, int>& inorderIndex, int low, int high) {
    if (low > high) {
        return nullptr;
    }
    TreeNode* node = new TreeNode(preorder[next++]);
    int mid = inorderIndex[node->val];
    node->left = buildSubtree(preorder, next, inorderIndex, low, mid - 1);
    node->right = buildSubtree(preorder, next, inorderIndex, mid + 1, high);
    return node;
}

class Solution {
public:
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        int n = inorder.size();
        unordered_map<int, int> inorderIndex;
        for (int i = 0; i < n; i++) {
            inorderIndex[inorder[i]] = i;
        }
        int next = 0;
        return buildSubtree(preorder, next, inorderIndex, 0, n - 1);
    }
};

// Approach: Treat 0 as -1 and store the first index of each running balance in a hash map.
// Time O(n), Space O(n)
class Solution {
public:
    int findMaxLength(vector<int>& nums) {
        int n = nums.size();
        unordered_map<int, int> firstSeenAt;
        firstSeenAt[0] = -1;
        int balance = 0;
        int bestLength = 0;
        for (int i = 0; i < n; i++) {
            balance += nums[i] == 1 ? 1 : -1;
            auto it = firstSeenAt.find(balance);
            if (it != firstSeenAt.end()) {
                bestLength = max(bestLength, i - it->second);
            } else {
                firstSeenAt[balance] = i;
            }
        }
        return bestLength;
    }
};

// Approach: Sieve of Eratosthenes, crossing out multiples starting from i * i.
// Time O(n log log n), Space O(n)
class Solution {
public:
    int countPrimes(int n) {
        if (n < 3) {
            return 0;
        }
        vector<bool> isComposite(n, false);
        int primes = 0;
        for (int i = 2; i < n; i++) {
            if (isComposite[i]) {
                continue;
            }
            primes++;
            // long long avoids overflow of i * i
            for (long long multiple = (long long)i * i; multiple < n; multiple += i) {
                isComposite[multiple] = true;
            }
        }
        return primes;
    }
};

// Approach: Kahn's topological sort; all courses can be taken if none is left in a cycle.
// Time O(V + E), Space O(V + E)
class Solution {
public:
    bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
        vector<vector<int>> unlocks(numCourses);
        vector<int> indegree(numCourses, 0);
        for (const auto& pair : prerequisites) {
            unlocks[pair[1]].push_back(pair[0]);
            indegree[pair[0]]++;
        }
        queue<int> queue;
        for (int course = 0; course < numCourses; course++) {
            if (indegree[course] == 0) {
                queue.push(course);
            }
        }
        int taken = 0;
        while (!queue.empty()) {
            int course = queue.front();
            queue.pop();
            taken++;
            for (int next : unlocks[course]) {
                if (--indegree[next] == 0) {
                    queue.push(next);
                }
            }
        }
        return taken == numCourses;
    }
};

// Approach: Bucket points by value, then solve it like House Robber over the value line.
// Time O(n + maxValue), Space O(maxValue)
class Solution {
public:
    int deleteAndEarn(vector<int>& nums) {
        vector<int> points(*max_element(nums.begin(), nums.end()) + 1, 0);
        for (int x : nums) {
            points[x] += x;
        }
        int take = 0;
        int skip = 0;
        for (int value : points) {
            int newTake = skip + value;
            skip = max(take, skip);
            take = newTake;
        }
        return max(take, skip);
    }
};

// Approach: 1D DP counting ways to form prefixes of t, updated right to left for each char of s.
// Time O(n * m), Space O(m)
class Solution {
public:
    int numDistinct(string s, string t) {
        int m = t.size();
        // ways[j] = number of ways to form t[0..j) from the part of s seen so far
        vector<long long> ways(m + 1, 0);
        ways[0] = 1;
        for (char ch : s) {
            for (int j = m; j >= 1; j--) {
                if (t[j - 1] == ch) {
                    ways[j] += ways[j - 1];
                }
            }
        }
        return ways[m];
    }
};

// Approach: Read the title as a base-26 number with digits A=1 .. Z=26.
// Time O(n), Space O(1)
class Solution {
public:
    int titleToNumber(string columnTitle) {
        long long number = 0;
        for (char ch : columnTitle) {
            number = number * 26 + (ch - 'A' + 1);
        }
        return number;
    }
};

// Approach: Two binary searches, lower_bound and upper_bound, give the range edges.
// Time O(log n), Space O(1)
class Solution {
public:
    vector<int> searchRange(vector<int>& nums, int target) {
        int n = nums.size();
        int first = lower_bound(nums.begin(), nums.end(), target) - nums.begin();
        if (first == n || nums[first] != target) {
            return {-1, -1};
        }
        int last = upper_bound(nums.begin(), nums.end(), target) - nums.begin() - 1;
        return {first, last};
    }
};

// Approach: Floyd's cycle detection, treating nums[i] as the next pointer of node i.
// Time O(n), Space O(1)
class Solution {
public:
    int findDuplicate(vector<int>& nums) {
        int slow = nums[0];
        int fast = nums[0];
        do {
            slow = nums[slow];
            fast = nums[nums[fast]];
        } while (slow != fast);

        // The cycle entrance is the duplicated value.
        slow = nums[0];
        while (slow != fast) {
            slow = nums[slow];
            fast = nums[fast];
        }
        return slow;
    }
};

// Approach: Count each character, then return the first index whose count is one.
// Time O(n), Space O(1)
class Solution {
public:
    int firstUniqChar(string s) {
        int n = s.size();
        int counts[256] = {0};
        for (unsigned char ch : s) {
            counts[ch]++;
        }
        for (int i = 0; i < n; i++) {
            if (counts[(unsigned char)s[i]] == 1) {
                return i;
            }
        }
        return -1;
    }
};

// Approach: Backtracking that only adds a close bracket when it has a matching open one.
// Time O(4^n / sqrt(n)), Space O(n) recursion depth excluding output
void buildParentheses(string current, int opened, int closed, int n, vector<string>& result) {
    if ((int)current.size() == 2 * n) {
        result.push_back(current);
        return;
    }
    if (opened < n) {
        buildParentheses(current + "(", opened + 1, closed, n, result);
    }
    if (closed < opened) {
        buildParentheses(current + ")", opened, closed + 1, n, result);
    }
}

class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> result;
        buildParentheses("", 0, 0, n, result);
        return result;
    }
};

// Approach: Floyd's cycle detection on the sequence of digit-square sums.
// Time O(log n), Space O(1)
int digitSquareSum(long long x) {
    int total = 0;
    while (x > 0) {
        int digit = x % 10;
        total += digit * digit;
        x /= 10;
    }
    return total;
}

class Solution {
public:
    bool isHappy(int n) {
        long long slow = n;
        long long fast = digitSquareSum(n);
        while (fast != 1 && slow != fast) {
            slow = digitSquareSum(slow);
            fast = digitSquareSum(digitSquareSum(fast));
        }
        return fast == 1;
    }
};

// Approach: Post-order DP returning the best loot with and without robbing each node.
// Time O(n), Space O(h) for tree height h
pair<int, int> robSubtree(TreeNode* node) {
    // returns {best if node is robbed, best if node is skipped}
    if (!node) {
        return {0, 0};
    }
    auto left = robSubtree(node->left);
    auto right = robSubtree(node->right);
    int robbed = node->val + left.second + right.second;
    int skipped = max(left.first, left.second) + max(right.first, right.second);
    return {robbed, skipped};
}

class Solution {
public:
    int rob(TreeNode* root) {
        auto best = robSubtree(root);
        return max(best.first, best.second);
    }
};

// Approach: DP over prefixes of s1 and s2, compressed to a single row.
// Time O(m * n), Space O(n)
class Solution {
public:
    bool isInterleave(string s1, string s2, string s3) {
        int m = s1.size();
        int n = s2.size();
        if (m + n != (int)s3.size()) {
            return false;
        }
        // canForm[j]: s3[0..i+j) is an interleaving of s1[0..i) and s2[0..j)
        vector<char> canForm(n + 1, 0);
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0 && j == 0) {
                    canForm[j] = 1;
                    continue;
                }
                bool ok = false;
                if (i > 0 && canForm[j] && s1[i - 1] == s3[i + j - 1]) {
                    ok = true;
                }
                if (j > 0 && canForm[j - 1] && s2[j - 1] == s3[i + j - 1]) {
                    ok = true;
                }
                canForm[j] = ok;
            }
        }
        return canForm[n];
    }
};

// Approach: BFS two-coloring of every component; an edge within one color means not bipartite.
// Time O(V + E), Space O(V)
class Solution {
public:
    bool isBipartite(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<int> color(n, -1);
        for (int start = 0; start < n; start++) {
            if (color[start] != -1) {
                continue;
            }
            color[start] = 0;
            queue<int> pending;
            pending.push(start);
            while (!pending.empty()) {
                int node = pending.front();
                pending.pop();
                for (int next : graph[node]) {
                    if (color[next] == -1) {
                        color[next] = color[node] ^ 1;
                        pending.push(next);
                    } else if (color[next] == color[node]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
};

// Approach: Keep a two-way character mapping and reject any conflict.
// Time O(n), Space O(1) for a fixed alphabet
class Solution {
public:
    bool isIsomorphic(string s, string t) {
        unordered_map<char, char> sToT;
        unordered_map<char, char> tToS;
        int n = s.size();
        for (int i = 0; i < n; i++) {
            char from = s[i];
            char to = t[i];
            if (sToT.count(from) && sToT[from] != to) {
                return false;
            }
            if (tToS.count(to) && tToS[to] != from) {
                return false;
            }
            sToT[from] = to;
            tToS[to] = from;
        }
        return true;
    }
};

// Approach: Binary search the smallest eating speed that finishes within h hours.
// Time O(n log maxPile), Space O(1)
class Solution {
public:
    int minEatingSpeed(vector<int>& piles, int h) {
        int low = 1;
        int high = *max_element(piles.begin(), piles.end());
        while (low < high) {
            int speed = low + (high - low) / 2;
            long long hours = 0;
            for (int pile : piles) {
                hours += (pile + speed - 1) / speed;
            }
            if (hours <= h) {
                high = speed;
            } else {
                low = speed + 1;
            }
        }
        return low;
    }
};

// Approach: Flatten the matrix, sort it and take the k-th element.
// Time O(N log N) for N cells, Space O(N)
class Solution {
public:
    int kthSmallest(vector<vector<int>>& matrix, int k) {
        vector<int> values;
        for (const auto& row : matrix) {
            for (int value : row) {
                values.push_back(value);
            }
        }
        sort(values.begin(), values.end());
        return values[k - 1];
    }
};

// Approach: Greedy change-making that tracks the count of $5 and $10 bills held.
// Time O(n), Space O(1)
class Solution {
public:
    bool lemonadeChange(vector<int>& bills) {
        int fives = 0;
        int tens = 0;
        for (int bill : bills) {
            if (bill == 5) {
                fives++;
            } else if (bill == 10) {
                if (fives == 0) {
                    return false;
                }
                fives--;
                tens++;
            } else if (tens > 0 && fives > 0) {
                // Prefer 10 + 5 so the more flexible 5s are kept.
                tens--;
                fives--;
            } else if (fives >= 3) {
                fives -= 3;
            } else {
                return false;
            }
        }
        return true;
    }
};

// Approach: Hash set; only start counting from numbers that begin a run.
// Time O(n), Space O(n)
class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        unordered_set<int> values(nums.begin(), nums.end());
        int bestLength = 0;
        for (int start : values) {
            if (values.count(start - 1)) {
                continue;
            }
            int length = 1;
            while (values.count(start + length)) {
                length++;
            }
            bestLength = max(bestLength, length);
        }
        return bestLength;
    }
};

// Approach: Sliding window valid while at most k characters differ from the most common one.
// Time O(n), Space O(1)
class Solution {
public:
    int characterReplacement(string s, int k) {
        int n = s.size();
        vector<int> counts(26, 0);
        int bestLength = 0;
        int windowStart = 0;
        int maxCount = 0;
        for (int windowEnd = 0; windowEnd < n; windowEnd++) {
            maxCount = max(maxCount, ++counts[s[windowEnd] - 'A']);
            // maxCount never needs to shrink: a smaller value cannot beat bestLength.
            while (windowEnd - windowStart + 1 - maxCount > k) {
                counts[s[windowStart++] - 'A']--;
            }
            bestLength = max(bestLength, windowEnd - windowStart + 1);
        }
        return bestLength;
    }
};

// Approach: Stack of indices, with the last unmatched position at the bottom as a base.
// Time O(n), Space O(n)
class Solution {
public:
    int longestValidParentheses(string s) {
        int n = s.size();
        int bestLength = 0;
        vector<int> stack = {-1};
        for (int i = 0; i < n; i++) {
            if (s[i] == '(') {
                stack.push_back(i);
                continue;
            }
            stack.pop_back();
            if (stack.empty()) {
                stack.push_back(i);
            } else {
                bestLength = max(bestLength, i - stack.back());
            }
        }
        return bestLength;
    }
};

// Approach: Boyer-Moore voting; the majority element survives all pairwise cancellations.
// Time O(n), Space O(1)
class Solution {
public:
    int majorityElement(vector<int>& nums) {
        int candidate = 0;
        int votes = 0;
        for (int x : nums) {
            if (votes == 0) {
                candidate = x;
            }
            votes += (x == candidate) ? 1 : -1;
        }
        return candidate;
    }
};

// Approach: DP where dp[i][j] is the side of the largest square ending at corner (i, j).
// Time O(rows * cols), Space O(rows * cols)
class Solution {
public:
    int maximalSquare(vector<vector<char>>& matrix) {
        int rows = matrix.size();
        int cols = matrix[0].size();
        vector<vector<int>> dp(rows + 1, vector<int>(cols + 1, 0));
        int bestSide = 0;
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (matrix[i - 1][j - 1] == '1') {
                    dp[i][j] = 1 + min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});
                    bestSide = max(bestSide, dp[i][j]);
                }
            }
        }
        return bestSide * bestSide;
    }
};

// Approach: Kadane's algorithm; extend the current subarray or restart at this element.
// Time O(n), Space O(1)
class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        int n = nums.size();
        int bestSum = nums[0];
        int currentSum = nums[0];
        for (int i = 1; i < n; i++) {
            currentSum = max(nums[i], currentSum + nums[i]);
            bestSum = max(bestSum, currentSum);
        }
        return bestSum;
    }
};

// Approach: Sort start and end times separately and sweep, reusing a room when one has freed up.
// Time O(n log n), Space O(n)
class Solution {
public:
    int minMeetingRooms(vector<vector<int>>& intervals) {
        vector<int> starts;
        vector<int> ends;
        for (const auto& interval : intervals) {
            starts.push_back(interval[0]);
            ends.push_back(interval[1]);
        }
        sort(starts.begin(), starts.end());
        sort(ends.begin(), ends.end());
        int rooms = 0;
        int nextToEnd = 0;
        for (int start : starts) {
            if (start < ends[nextToEnd]) {
                rooms++;
            } else {
                nextToEnd++;
            }
        }
        return rooms;
    }
};

// Approach: Splice the smaller head of the two lists onto a tail pointer repeatedly.
// Time O(n + m), Space O(1)
class Solution {
public:
    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {
        ListNode dummy(0);
        ListNode* tail = &dummy;
        while (list1 && list2) {
            if (list1->val <= list2->val) {
                tail->next = list1;
                list1 = list1->next;
            } else {
                tail->next = list2;
                list2 = list2->next;
            }
            tail = tail->next;
        }
        tail->next = list1 ? list1 : list2;
        return dummy.next;
    }
};

// Approach: Prim's algorithm on the implicit complete graph with Manhattan distances.
// Time O(n^2), Space O(n)
class Solution {
public:
    int minCostConnectPoints(vector<vector<int>>& points) {
        int n = points.size();
        vector<long long> cheapestEdge(n, LLONG_MAX);
        vector<bool> inTree(n, false);
        cheapestEdge[0] = 0;
        long long totalCost = 0;
        for (int added = 0; added < n; added++) {
            int closest = -1;
            for (int i = 0; i < n; i++) {
                if (!inTree[i] && (closest == -1 || cheapestEdge[i] < cheapestEdge[closest])) {
                    closest = i;
                }
            }
            inTree[closest] = true;
            totalCost += cheapestEdge[closest];
            for (int other = 0; other < n; other++) {
                if (inTree[other]) {
                    continue;
                }
                long long distance =
                    llabs((long long)points[closest][0] - points[other][0]) +
                    llabs((long long)points[closest][1] - points[other][1]);
                cheapestEdge[other] = min(cheapestEdge[other], distance);
            }
        }
        return totalCost;
    }
};

// Approach: Row-by-row DP; each cell adds the cheapest of the three cells above it.
// Time O(n^2), Space O(n)
class Solution {
public:
    int minFallingPathSum(vector<vector<int>>& matrix) {
        int n = matrix.size();
        vector<int> previous = matrix[0];
        for (int row = 1; row < n; row++) {
            vector<int> current(n);
            for (int col = 0; col < n; col++) {
                int cheapestAbove = previous[col];
                if (col > 0) {
                    cheapestAbove = min(cheapestAbove, previous[col - 1]);
                }
                if (col < n - 1) {
                    cheapestAbove = min(cheapestAbove, previous[col + 1]);
                }
                current[col] = matrix[row][col] + cheapestAbove;
            }
            previous = current;
        }
        return *min_element(previous.begin(), previous.end());
    }
};

// Approach: Sliding window; shrink from the left whenever the sum reaches the target.
// Time O(n), Space O(1)
class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int n = nums.size();
        int bestLength = n + 1;
        int windowStart = 0;
        long long windowSum = 0;
        for (int windowEnd = 0; windowEnd < n; windowEnd++) {
            windowSum += nums[windowEnd];
            while (windowSum >= target) {
                bestLength = min(bestLength, windowEnd - windowStart + 1);
                windowSum -= nums[windowStart++];
            }
        }
        return bestLength == n + 1 ? 0 : bestLength;
    }
};

// Approach: Two pointers; swap each non-zero element into the next free front slot.
// Time O(n), Space O(1)
class Solution {
public:
    void moveZeroes(vector<int>& nums) {
        int n = nums.size();
        int nextSlot = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] != 0) {
                swap(nums[i], nums[nextSlot++]);
            }
        }
    }
};

// Approach: Monotonic stack over two passes of the array to simulate the circular wrap.
// Time O(n), Space O(n)
class Solution {
public:
    vector<int> nextGreaterElements(vector<int>& nums) {
        int n = nums.size();
        vector<int> result(n, -1);
        vector<int> waiting;  // indices still looking for a greater element
        for (int i = 0; i < 2 * n; i++) {
            int value = nums[i % n];
            while (!waiting.empty() && nums[waiting.back()] < value) {
                result[waiting.back()] = value;
                waiting.pop_back();
            }
            if (i < n) {
                waiting.push_back(i);
            }
        }
        return result;
    }
};

// Approach: Brian Kernighan's trick; n & (n - 1) clears the lowest set bit.
// Time O(number of set bits), Space O(1)
class Solution {
public:
    int hammingWeight(int n) {
        int bits = 0;
        while (n) {
            n &= n - 1;
            bits++;
        }
        return bits;
    }
};

// Approach: Union-Find with path compression; each successful union merges two provinces.
// Time O(n^2 * alpha(n)), Space O(n)
class Solution {
public:
    int findCircleNum(vector<vector<int>>& isConnected) {
        int n = isConnected.size();
        vector<int> parent(n);
        iota(parent.begin(), parent.end(), 0);
        auto findRoot = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };

        int provinces = n;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n && j < (int)isConnected[i].size(); j++) {
                if (isConnected[i][j] != 1) {
                    continue;
                }
                int rootI = findRoot(i);
                int rootJ = findRoot(j);
                if (rootI != rootJ) {
                    parent[rootI] = rootJ;
                    provinces--;
                }
            }
        }
        return provinces;
    }
};

// Approach: Reverse only the second half of the digits and compare it with the first half.
// Time O(log x), Space O(1)
class Solution {
public:
    bool isPalindrome(int x) {
        if (x < 0 || (x % 10 == 0 && x != 0)) {
            return false;
        }
        int reversedHalf = 0;
        while (x > reversedHalf) {
            reversedHalf = reversedHalf * 10 + x % 10;
            x /= 10;
        }
        // For an odd digit count the middle digit is dropped with reversedHalf / 10.
        return x == reversedHalf || x == reversedHalf / 10;
    }
};

// Approach: 0/1 knapsack boolean DP for a subset summing to half the total.
// Time O(n * sum), Space O(sum)
class Solution {
public:
    bool canPartition(vector<int>& nums) {
        int total = 0;
        for (int x : nums) {
            total += x;
        }
        if (total % 2 != 0) {
            return false;
        }
        int half = total / 2;
        vector<bool> reachable(half + 1, false);
        reachable[0] = true;
        for (int x : nums) {
            // Go downwards so each number is used at most once.
            for (int sum = half; sum >= x; sum--) {
                if (reachable[sum - x]) {
                    reachable[sum] = true;
                }
            }
        }
        return reachable[half];
    }
};

// Approach: Build each row from the previous one; inner cells are the sum of the two above.
// Time O(numRows^2), Space O(numRows^2)
class Solution {
public:
    vector<vector<int>> generate(int numRows) {
        vector<vector<int>> triangle;
        for (int i = 0; i < numRows; i++) {
            vector<int> row(i + 1, 1);
            for (int j = 1; j < i; j++) {
                row[j] = triangle[i - 1][j - 1] + triangle[i - 1][j];
            }
            triangle.push_back(row);
        }
        return triangle;
    }
};

// Approach: Dijkstra where a path's cost is the largest height difference along it.
// Time O(m * n log(m * n)), Space O(m * n)
class Solution {
public:
    int minimumEffortPath(vector<vector<int>>& heights) {
        int m = heights.size();
        int n = heights[0].size();
        vector<vector<int>> bestEffort(m, vector<int>(n, INT_MAX));
        bestEffort[0][0] = 0;
        using State = tuple<int, int, int>;  // effort, row, col
        priority_queue<State, vector<State>, greater<>> queue;
        queue.push({0, 0, 0});
        const int rowStep[4] = {1, -1, 0, 0};
        const int colStep[4] = {0, 0, 1, -1};
        while (!queue.empty()) {
            auto [effort, row, col] = queue.top();
            queue.pop();
            if (effort > bestEffort[row][col]) {
                continue;
            }
            if (row == m - 1 && col == n - 1) {
                return effort;
            }
            for (int d = 0; d < 4; d++) {
                int nextRow = row + rowStep[d];
                int nextCol = col + colStep[d];
                if (nextRow < 0 || nextRow >= m || nextCol < 0 || nextCol >= n) {
                    continue;
                }
                int nextEffort = max(effort, abs(heights[nextRow][nextCol] - heights[row][col]));
                if (nextEffort < bestEffort[nextRow][nextCol]) {
                    bestEffort[nextRow][nextCol] = nextEffort;
                    queue.push({nextEffort, nextRow, nextCol});
                }
            }
        }
        return 0;
    }
};

// Approach: Add one from the last digit, carrying through trailing nines.
// Time O(n), Space O(1) (O(n) only when every digit is 9)
class Solution {
public:
    vector<int> plusOne(vector<int>& digits) {
        for (int i = (int)digits.size() - 1; i >= 0; i--) {
            if (digits[i] < 9) {
                digits[i]++;
                return digits;
            }
            digits[i] = 0;
        }
        digits.insert(digits.begin(), 1);
        return digits;
    }
};

// Approach: Union-Find; the first edge joining two already-connected nodes closes a cycle.
// Time O(n * alpha(n)), Space O(n)
class Solution {
public:
    vector<int> findRedundantConnection(vector<vector<int>>& edges) {
        int n = edges.size();
        vector<int> parent(n + 1);
        iota(parent.begin(), parent.end(), 0);
        auto findRoot = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };
        for (const auto& edge : edges) {
            int rootA = findRoot(edge[0]);
            int rootB = findRoot(edge[1]);
            if (rootA == rootB) {
                return {edge[0], edge[1]};
            }
            parent[rootA] = rootB;
        }
        return {};
    }
};

// Approach: Single pass that unlinks a node whenever it equals its successor.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* deleteDuplicates(ListNode* head) {
        ListNode* node = head;
        while (node && node->next) {
            if (node->val == node->next->val) {
                node->next = node->next->next;
            } else {
                node = node->next;
            }
        }
        return head;
    }
};

// Approach: Two pointers n nodes apart; when the lead hits the end, the other precedes the target.
// Time O(L) for list length L, Space O(1)
class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        ListNode dummy(0);
        dummy.next = head;
        ListNode* lead = &dummy;
        ListNode* trail = &dummy;
        for (int i = 0; i < n; i++) {
            lead = lead->next;
        }
        while (lead->next) {
            lead = lead->next;
            trail = trail->next;
        }
        trail->next = trail->next->next;
        return dummy.next;
    }
};

// Approach: Peel off digits into a 64-bit result and return 0 if it leaves the int range.
// Time O(log x), Space O(1)
class Solution {
public:
    int reverse(int x) {
        long long remaining = x;
        long long reversed = 0;
        bool negative = remaining < 0;
        if (negative) {
            remaining = -remaining;
        }
        while (remaining > 0) {
            reversed = reversed * 10 + remaining % 10;
            remaining /= 10;
        }
        if (negative) {
            reversed = -reversed;
        }
        return (reversed < INT_MIN || reversed > INT_MAX) ? 0 : reversed;
    }
};

// Approach: Find each group's k-th node, reverse the group in place and relink it.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        ListNode dummy(0);
        dummy.next = head;
        ListNode* groupPrev = &dummy;
        while (true) {
            ListNode* kth = groupPrev;
            for (int i = 0; i < k; i++) {
                kth = kth->next;
                if (!kth) {
                    return dummy.next;
                }
            }
            ListNode* groupNext = kth->next;
            ListNode* previous = groupNext;
            ListNode* node = groupPrev->next;
            while (node != groupNext) {
                ListNode* next = node->next;
                node->next = previous;
                previous = node;
                node = next;
            }
            ListNode* groupFirst = groupPrev->next;
            groupPrev->next = kth;
            groupPrev = groupFirst;
        }
    }
};

// Approach: Transpose the matrix, then reverse each row to rotate 90 degrees clockwise.
// Time O(n^2), Space O(1)
class Solution {
public:
    void rotate(vector<vector<int>>& matrix) {
        int n = matrix.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                swap(matrix[i][j], matrix[j][i]);
            }
        }
        for (auto& row : matrix) {
            reverse(row.begin(), row.end());
        }
    }
};

// Approach: Recursively compare both trees node by node.
// Time O(n), Space O(h) for tree height h
class Solution {
public:
    bool isSameTree(TreeNode* p, TreeNode* q) {
        if (!p && !q) {
            return true;
        }
        if (!p || !q || p->val != q->val) {
            return false;
        }
        return isSameTree(p->left, q->left) && isSameTree(p->right, q->right);
    }
};

// Approach: Binary search for the first index whose value is not less than target.
// Time O(log n), Space O(1)
class Solution {
public:
    int searchInsert(vector<int>& nums, int target) {
        int low = 0;
        int high = nums.size();
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
};

// Approach: XOR all numbers; paired values cancel and the single one remains.
// Time O(n), Space O(1)
class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int result = 0;
        for (int x : nums) {
            result ^= x;
        }
        return result;
    }
};

// Approach: Dutch national flag; three pointers partition into 0s, 1s and 2s in one pass.
// Time O(n), Space O(1)
class Solution {
public:
    void sortColors(vector<int>& nums) {
        int zeroEnd = 0;
        int i = 0;
        int twoStart = (int)nums.size() - 1;
        while (i <= twoStart) {
            if (nums[i] == 0) {
                swap(nums[zeroEnd++], nums[i++]);
            } else if (nums[i] == 2) {
                swap(nums[i], nums[twoStart--]);
            } else {
                i++;
            }
        }
    }
};

// Approach: Binary search the answer; greedily count the subarrays needed for a given max sum.
// Time O(n log(sum)), Space O(1)
class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        int low = *max_element(nums.begin(), nums.end());
        int high = accumulate(nums.begin(), nums.end(), 0);
        while (low < high) {
            int maxSum = low + (high - low) / 2;
            int parts = 1;
            int currentSum = 0;
            for (int x : nums) {
                if (currentSum + x > maxSum) {
                    parts++;
                    currentSum = x;
                } else {
                    currentSum += x;
                }
            }
            if (parts <= k) {
                high = maxSum;
            } else {
                low = maxSum + 1;
            }
        }
        return low;
    }
};

// Approach: Prefix sums with a hash map counting how often each prefix has occurred.
// Time O(n), Space O(n)
class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<long long, int> prefixCount;
        prefixCount[0] = 1;
        long long prefixSum = 0;
        int subarrays = 0;
        for (int x : nums) {
            prefixSum += x;
            auto it = prefixCount.find(prefixSum - k);
            if (it != prefixCount.end()) {
                subarrays += it->second;
            }
            prefixCount[prefixSum]++;
        }
        return subarrays;
    }
};

// Approach: Add with bit operations: XOR gives the sum without carry, AND shifted gives the carry.
// Time O(1), Space O(1)
class Solution {
public:
    int getSum(int a, int b) {
        // Unsigned arithmetic avoids undefined behaviour when the carry shifts out.
        unsigned sum = a;
        unsigned carry = b;
        while (carry) {
            unsigned nextCarry = (sum & carry) << 1;
            sum ^= carry;
            carry = nextCarry;
        }
        return sum;
    }
};

// Approach: Rewire each adjacent pair behind a dummy head.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* swapPairs(ListNode* head) {
        ListNode dummy(0);
        dummy.next = head;
        ListNode* previous = &dummy;
        while (previous->next && previous->next->next) {
            ListNode* first = previous->next;
            ListNode* second = first->next;
            first->next = second->next;
            second->next = first;
            previous->next = second;
            previous = first;
        }
        return dummy.next;
    }
};

// Approach: Reduce to counting subsets that sum to (total + target) / 2, using 0/1 knapsack.
// Time O(n * sum), Space O(sum)
class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        int total = 0;
        for (int x : nums) {
            total += x;
        }
        // With positives P and negatives N: P - N = target and P + N = total.
        if (abs(target) > total || (total + target) % 2 != 0) {
            return 0;
        }
        int subsetSum = (total + target) / 2;
        vector<long long> ways(subsetSum + 1, 0);
        ways[0] = 1;
        for (int x : nums) {
            for (int sum = subsetSum; sum >= x; sum--) {
                ways[sum] += ways[sum - x];
            }
        }
        return ways[subsetSum];
    }
};

// Approach: Two pointers; the side with the lower wall is bounded by its own running maximum.
// Time O(n), Space O(1)
class Solution {
public:
    int trap(vector<int>& height) {
        int left = 0;
        int right = (int)height.size() - 1;
        int leftMax = 0;
        int rightMax = 0;
        long long water = 0;
        while (left < right) {
            if (height[left] < height[right]) {
                leftMax = max(leftMax, height[left]);
                water += leftMax - height[left++];
            } else {
                rightMax = max(rightMax, height[right]);
                water += rightMax - height[right--];
            }
        }
        return water;
    }
};

// Approach: Build ugly numbers in order with three pointers for the multiples of 2, 3 and 5.
// Time O(n), Space O(n)
class Solution {
public:
    int nthUglyNumber(int n) {
        vector<long long> ugly(n, 1);
        int index2 = 0;
        int index3 = 0;
        int index5 = 0;
        for (int i = 1; i < n; i++) {
            long long by2 = ugly[index2] * 2;
            long long by3 = ugly[index3] * 3;
            long long by5 = ugly[index5] * 5;
            long long next = min({by2, by3, by5});
            ugly[i] = next;
            if (next == by2) {
                index2++;
            }
            if (next == by3) {
                index3++;
            }
            if (next == by5) {
                index5++;
            }
        }
        return ugly[n - 1];
    }
};

// Approach: Two strings are anagrams exactly when their sorted forms are equal.
// Time O(n log n), Space O(1) extra (sorts the copies in place)
class Solution {
public:
    bool isAnagram(string s, string t) {
        sort(s.begin(), s.end());
        sort(t.begin(), t.end());
        return s == t;
    }
};

// Approach: Stack of open brackets; every closer must match the most recent opener.
// Time O(n), Space O(n)
class Solution {
public:
    bool isValid(string s) {
        string openBrackets;
        for (char ch : s) {
            if (ch == '(' || ch == '[' || ch == '{') {
                openBrackets.push_back(ch);
                continue;
            }
            if (openBrackets.empty()) {
                return false;
            }
            char open = openBrackets.back();
            openBrackets.pop_back();
            bool matches = (ch == ')' && open == '(') ||
                           (ch == ']' && open == '[') ||
                           (ch == '}' && open == '{');
            if (!matches) {
                return false;
            }
        }
        return openBrackets.empty();
    }
};

// Approach: Greedy two-pointer matching that backtracks to the most recent '*' on a mismatch.
// Time O(n * m), Space O(1)
class Solution {
public:
    bool isMatch(string s, string p) {
        int n = s.size();
        int m = p.size();
        int i = 0;
        int j = 0;
        int starIndex = -1;
        int matchedUpTo = 0;
        while (i < n) {
            if (j < m && (p[j] == '?' || p[j] == s[i])) {
                i++;
                j++;
            } else if (j < m && p[j] == '*') {
                starIndex = j;
                matchedUpTo = i;
                j++;
            } else if (starIndex != -1) {
                // Let the last '*' absorb one more character of s.
                j = starIndex + 1;
                matchedUpTo++;
                i = matchedUpTo;
            } else {
                return false;
            }
        }
        while (j < m && p[j] == '*') {
            j++;
        }
        return j == m;
    }
};

// Approach: Sort, fix the first number, then sweep two pointers inward and skip duplicates.
// Time O(n^2), Space O(1) extra (excluding output and sort)
class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        vector<vector<int>> result;
        int n = nums.size();
        for (int i = 0; i + 2 < n; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            int left = i + 1;
            int right = n - 1;
            while (left < right) {
                long long sum = (long long)nums[i] + nums[left] + nums[right];
                if (sum < 0) {
                    left++;
                } else if (sum > 0) {
                    right--;
                } else {
                    result.push_back({nums[i], nums[left], nums[right]});
                    left++;
                    right--;
                    while (left < right && nums[left] == nums[left - 1]) left++;
                }
            }
        }
        return result;
    }
};

// Approach: Greedy; give each cookie, smallest first, to the least greedy unsatisfied child.
// Time O(n log n + m log m), Space O(1) extra
class Solution {
public:
    int findContentChildren(vector<int>& g, vector<int>& s) {
        sort(g.begin(), g.end());
        sort(s.begin(), s.end());
        size_t satisfied = 0;
        for (int cookie : s) {
            if (satisfied < g.size() && cookie >= g[satisfied]) satisfied++;
        }
        return satisfied;
    }
};

// Approach: Greedy; collect every positive day-to-day price increase.
// Time O(n), Space O(1)
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int profit = 0;
        for (size_t i = 1; i < prices.size(); i++) {
            profit += max(0, prices[i] - prices[i - 1]);
        }
        return profit;
    }
};

// Approach: Classic binary search that halves the sorted range each step.
// Time O(log n), Space O(1)
class Solution {
public:
    int search(vector<int>& nums, int target) {
        int low = 0;
        int high = (int)nums.size() - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] == target) return mid;
            if (nums[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }
};

// Approach: Post-order DFS returning the best downward gain while tracking the best bent path.
// Time O(n), Space O(h)
long long maxDownwardGain(TreeNode* node, long long& bestPath) {
    if (!node) return 0;
    long long leftGain = max(maxDownwardGain(node->left, bestPath), 0LL);
    long long rightGain = max(maxDownwardGain(node->right, bestPath), 0LL);
    bestPath = max(bestPath, node->val + leftGain + rightGain);
    return node->val + max(leftGain, rightGain);
}

class Solution {
public:
    int maxPathSum(TreeNode* root) {
        long long bestPath = LLONG_MIN;
        maxDownwardGain(root, bestPath);
        return bestPath;
    }
};

// Approach: The AND of a range is the common binary prefix of its two endpoints.
// Time O(log right), Space O(1)
class Solution {
public:
    int rangeBitwiseAnd(int left, int right) {
        int shift = 0;
        while (left != right) {
            left >>= 1;
            right >>= 1;
            shift++;
        }
        return left << shift;
    }
};

// Approach: Two greedy passes, left-to-right then right-to-left, to satisfy both neighbours.
// Time O(n), Space O(n)
class Solution {
public:
    int candy(vector<int>& ratings) {
        int n = ratings.size();
        vector<int> candies(n, 1);
        for (int i = 1; i < n; i++) {
            if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; i--) {
            if (ratings[i] > ratings[i + 1]) {
                candies[i] = max(candies[i], candies[i + 1] + 1);
            }
        }
        return accumulate(candies.begin(), candies.end(), 0);
    }
};

// Approach: Bellman-Ford limited to k+1 edge relaxations, using a copy per round.
// Time O(k * E), Space O(n)
class Solution {
public:
    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {
        const long long INF = LLONG_MAX / 4;
        vector<long long> cost(n, INF);
        cost[src] = 0;
        for (int round = 0; round <= k; round++) {
            vector<long long> next = cost;
            for (const auto& flight : flights) {
                int from = flight[0];
                int to = flight[1];
                next[to] = min(next[to], cost[from] + flight[2]);
            }
            cost = next;
        }
        return cost[dst] >= INF ? -1 : cost[dst];
    }
};

// Approach: Unbounded knapsack counting combinations, with coins as the outer loop.
// Time O(amount * coins), Space O(amount)
class Solution {
public:
    int change(int amount, vector<int>& coins) {
        vector<long long> ways(amount + 1, 0);
        ways[0] = 1;
        for (int coin : coins) {
            for (int total = coin; total <= amount; total++) {
                ways[total] += ways[total - coin];
            }
        }
        return ways[amount];
    }
};

// Approach: Two pointers from both ends, always moving the shorter wall inward.
// Time O(n), Space O(1)
class Solution {
public:
    int maxArea(vector<int>& height) {
        int left = 0;
        int right = (int)height.size() - 1;
        int bestArea = 0;
        while (left < right) {
            int area = (right - left) * min(height[left], height[right]);
            bestArea = max(bestArea, area);
            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }
        return bestArea;
    }
};

// Approach: Recursively count the root plus the nodes of both subtrees.
// Time O(n), Space O(h)
class Solution {
public:
    int countNodes(TreeNode* root) {
        if (!root) return 0;
        return 1 + countNodes(root->left) + countNodes(root->right);
    }
};

// Approach: 0/1 knapsack counting subsets, iterating sums downward so each item is used once.
// Time O(n * target), Space O(target)
class Solution {
public:
    int countSubsets(vector<int>& nums, int target) {
        vector<long long> ways(target + 1, 0);
        ways[0] = 1;
        for (int num : nums) {
            for (int sum = target; sum >= num; sum--) {
                ways[sum] += ways[sum - num];
            }
        }
        return ways[target];
    }
};

// Approach: Monotonic stack of indices waiting for a warmer day.
// Time O(n), Space O(n)
class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        vector<int> waitDays(n, 0);
        vector<int> pending;
        for (int i = 0; i < n; i++) {
            while (!pending.empty() && temperatures[pending.back()] < temperatures[i]) {
                int colderDay = pending.back();
                pending.pop_back();
                waitDays[colderDay] = i - colderDay;
            }
            pending.push_back(i);
        }
        return waitDays;
    }
};

// Approach: Post-order DFS computing heights; the diameter is the best left+right height sum.
// Time O(n), Space O(h)
int subtreeHeight(TreeNode* node, int& diameter) {
    if (!node) return 0;
    int leftHeight = subtreeHeight(node->left, diameter);
    int rightHeight = subtreeHeight(node->right, diameter);
    diameter = max(diameter, leftHeight + rightHeight);
    return 1 + max(leftHeight, rightHeight);
}

class Solution {
public:
    int diameterOfBinaryTree(TreeNode* root) {
        int diameter = 0;
        subtreeHeight(root, diameter);
        return diameter;
    }
};

// Approach: DP over prefixes; dp[i][j] is the edit distance between word1[0..i) and word2[0..j).
// Time O(n * m), Space O(n * m)
class Solution {
public:
    int minDistance(string word1, string word2) {
        int n = word1.size();
        int m = word2.size();
        vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
        for (int i = 0; i <= n; i++) dp[i][0] = i;
        for (int j = 0; j <= m; j++) dp[0][j] = j;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int substitute = dp[i - 1][j - 1] + (word1[i - 1] != word2[j - 1]);
                int remove = dp[i - 1][j] + 1;
                int insert = dp[i][j - 1] + 1;
                dp[i][j] = min({substitute, remove, insert});
            }
        }
        return dp[n][m];
    }
};

// Approach: Binary exponentiation, squaring the base and multiplying when the bit is set.
// Time O(log exp), Space O(1)
class Solution {
public:
    int powMod(int base, int exp, int mod) {
        long long modulus = mod;
        long long result = 1 % modulus;
        long long power = base % modulus;
        long long remaining = exp;
        while (remaining > 0) {
            if (remaining & 1) result = result * power % modulus;
            power = power * power % modulus;
            remaining >>= 1;
        }
        return result;
    }
};

// Approach: Union-Find with path halving; connected iff both endpoints share a root.
// Time O((n + E) * alpha(n)), Space O(n)
class Solution {
public:
    bool validPath(int n, vector<vector<int>>& edges, int source, int destination) {
        vector<int> parent(n);
        iota(parent.begin(), parent.end(), 0);
        function<int(int)> findRoot = [&](int node) {
            while (parent[node] != node) {
                parent[node] = parent[parent[node]];
                node = parent[node];
            }
            return node;
        };
        for (const auto& edge : edges) {
            parent[findRoot(edge[0])] = findRoot(edge[1]);
        }
        return findRoot(source) == findRoot(destination);
    }
};

// Approach: Net trust score; the judge is trusted by all n-1 others and trusts nobody.
// Time O(n + E), Space O(n)
class Solution {
public:
    int findJudge(int n, vector<vector<int>>& trust) {
        vector<int> score(n + 1, 0);
        for (const auto& pair : trust) {
            score[pair[0]]--;
            score[pair[1]]++;
        }
        for (int person = 1; person <= n; person++) {
            if (score[person] == n - 1) return person;
        }
        return -1;
    }
};

// Approach: In-place update; bit 0 holds the current state and bit 1 the next state.
// Time O(m * n), Space O(1)
class Solution {
public:
    void gameOfLife(vector<vector<int>>& board) {
        int m = board.size();
        int n = m ? board[0].size() : 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int liveNeighbors = 0;
                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        if (di == 0 && dj == 0) continue;
                        int ni = i + di;
                        int nj = j + dj;
                        if (ni >= 0 && ni < m && nj >= 0 && nj < n) {
                            liveNeighbors += board[ni][nj] & 1;
                        }
                    }
                }
                if (liveNeighbors == 3 || (board[i][j] && liveNeighbors == 2)) {
                    board[i][j] |= 2;
                }
            }
        }
        for (auto& row : board) {
            for (int& cell : row) cell >>= 1;
        }
    }
};

// Approach: Sort ascending; the first citation count that is at least the papers remaining wins.
// Time O(n log n), Space O(1) extra
class Solution {
public:
    int hIndex(vector<int>& citations) {
        sort(citations.begin(), citations.end());
        int n = citations.size();
        for (int i = 0; i < n; i++) {
            int papersAtLeast = n - i;
            if (citations[i] >= papersAtLeast) return papersAtLeast;
        }
        return 0;
    }
};

// Approach: DP keeping the best total if the previous house was robbed or skipped.
// Time O(n), Space O(1)
class Solution {
public:
    int rob(vector<int>& nums) {
        int robbed = 0;
        int skipped = 0;
        for (int money : nums) {
            int robbedNow = skipped + money;
            skipped = max(robbed, skipped);
            robbed = robbedNow;
        }
        return max(robbed, skipped);
    }
};

// Approach: Copy intervals before, merge the overlapping ones with the new one, copy the rest.
// Time O(n), Space O(n)
class Solution {
public:
    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {
        int start = newInterval[0];
        int end = newInterval[1];
        vector<vector<int>> result;
        size_t i = 0;
        size_t n = intervals.size();
        while (i < n && intervals[i][1] < start) {
            result.push_back(intervals[i++]);
        }
        while (i < n && intervals[i][0] <= end) {
            start = min(start, intervals[i][0]);
            end = max(end, intervals[i][1]);
            i++;
        }
        result.push_back({start, end});
        while (i < n) {
            result.push_back(intervals[i++]);
        }
        return result;
    }
};

// Approach: Count nums1 in a hash map, then consume matching counts while scanning sorted nums2.
// Time O(n + m log m), Space O(n)
class Solution {
public:
    vector<int> intersect(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> remaining;
        for (int num : nums1) remaining[num]++;
        sort(nums2.begin(), nums2.end());
        vector<int> result;
        for (int num : nums2) {
            auto it = remaining.find(num);
            if (it != remaining.end() && it->second > 0) {
                result.push_back(num);
                it->second--;
            }
        }
        return result;
    }
};

// Approach: Two pointers; advance in s whenever the current character of t matches.
// Time O(|t|), Space O(1)
class Solution {
public:
    bool isSubsequence(string s, string t) {
        size_t matched = 0;
        for (char ch : t) {
            if (matched < s.size() && s[matched] == ch) matched++;
        }
        return matched == s.size();
    }
};

// Approach: Greedy; track the farthest reachable index and fail if we fall behind it.
// Time O(n), Space O(1)
class Solution {
public:
    bool canJump(vector<int>& nums) {
        int farthest = 0;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            if (i > farthest) return false;
            farthest = max(farthest, i + nums[i]);
        }
        return true;
    }
};

// Approach: Keep a min-heap of size k; its top is the kth largest value.
// Time O(n log k), Space O(k)
class Solution {
public:
    int findKthLargest(vector<int>& nums, int k) {
        priority_queue<int, vector<int>, greater<int>> minHeap;
        for (int num : nums) {
            minHeap.push(num);
            if ((int)minHeap.size() > k) minHeap.pop();
        }
        return minHeap.top();
    }
};

// Approach: Monotonic stack of (start index, height); popped bars close off rectangles.
// Time O(n), Space O(n)
class Solution {
public:
    int largestRectangleArea(vector<int>& heights) {
        long long bestArea = 0;
        heights.push_back(0);  // sentinel that flushes the stack
        vector<pair<int, int>> stack;
        for (int i = 0; i < (int)heights.size(); i++) {
            int start = i;
            while (!stack.empty() && stack.back().second >= heights[i]) {
                auto [barStart, barHeight] = stack.back();
                stack.pop_back();
                bestArea = max(bestArea, (long long)barHeight * (i - barStart));
                start = barStart;
            }
            stack.push_back({start, heights[i]});
        }
        return bestArea;
    }
};

// Approach: Scan from the end, skip trailing spaces, then count the last word's letters.
// Time O(n), Space O(1)
class Solution {
public:
    int lengthOfLastWord(string s) {
        int i = (int)s.size() - 1;
        int length = 0;
        while (i >= 0 && s[i] == ' ') i--;
        while (i >= 0 && s[i] != ' ') {
            length++;
            i--;
        }
        return length;
    }
};

// Approach: Patience sorting; tails[i] is the smallest tail of any increasing run of length i+1.
// Time O(n log n), Space O(n)
class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        vector<int> tails;
        for (int num : nums) {
            auto it = lower_bound(tails.begin(), tails.end(), num);
            if (it == tails.end()) {
                tails.push_back(num);
            } else {
                *it = num;
            }
        }
        return tails.size();
    }
};

// Approach: Sliding window with character counts, shrinking while more than k distinct appear.
// Time O(n), Space O(k)
class Solution {
public:
    int lengthOfLongestSubstringKDistinct(string s, int k) {
        if (k == 0) return 0;
        unordered_map<char, int> counts;
        int windowStart = 0;
        int bestLength = 0;
        for (int windowEnd = 0; windowEnd < (int)s.size(); windowEnd++) {
            counts[s[windowEnd]]++;
            while ((int)counts.size() > k) {
                if (--counts[s[windowStart]] == 0) counts.erase(s[windowStart]);
                windowStart++;
            }
            bestLength = max(bestLength, windowEnd - windowStart + 1);
        }
        return bestLength;
    }
};

// Approach: Walk down from the root toward the side where both nodes lie until they split.
// Time O(h), Space O(1)
class Solution {
public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        while (root) {
            if (p->val < root->val && q->val < root->val) {
                root = root->left;
            } else if (p->val > root->val && q->val > root->val) {
                root = root->right;
            } else {
                return root;
            }
        }
        return nullptr;
    }
};

// Approach: Iterative DFS flood fill from every unvisited land cell, tracking the largest area.
// Time O(rows * cols), Space O(rows * cols)
class Solution {
public:
    int maxAreaOfIsland(vector<vector<int>>& grid) {
        int rows = grid.size();
        int cols = grid[0].size();
        int bestArea = 0;
        vector<vector<bool>> visited(rows, vector<bool>(cols, false));
        const int dRow[] = {1, -1, 0, 0};
        const int dCol[] = {0, 0, 1, -1};
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != 1 || visited[r][c]) continue;
                visited[r][c] = true;
                vector<pair<int, int>> stack = {{r, c}};
                int area = 0;
                while (!stack.empty()) {
                    auto [row, col] = stack.back();
                    stack.pop_back();
                    area++;
                    for (int d = 0; d < 4; d++) {
                        int nextRow = row + dRow[d];
                        int nextCol = col + dCol[d];
                        bool inside = nextRow >= 0 && nextRow < rows &&
                                      nextCol >= 0 && nextCol < cols;
                        if (inside && grid[nextRow][nextCol] == 1 && !visited[nextRow][nextCol]) {
                            visited[nextRow][nextCol] = true;
                            stack.push_back({nextRow, nextCol});
                        }
                    }
                }
                bestArea = max(bestArea, area);
            }
        }
        return bestArea;
    }
};

// Approach: Recursion; depth is one plus the deeper of the two subtrees.
// Time O(n), Space O(h)
class Solution {
public:
    int maxDepth(TreeNode* root) {
        if (!root) return 0;
        return 1 + max(maxDepth(root->left), maxDepth(root->right));
    }
};

// Approach: Kadane for max and min subarrays; the circular best is total minus the min subarray.
// Time O(n), Space O(1)
class Solution {
public:
    int maxSubarraySumCircular(vector<int>& nums) {
        long long total = 0;
        long long currentMax = 0;
        long long currentMin = 0;
        long long bestMax = nums[0];
        long long bestMin = nums[0];
        for (int num : nums) {
            total += num;
            currentMax = max(currentMax + num, (long long)num);
            bestMax = max(bestMax, currentMax);
            currentMin = min(currentMin + num, (long long)num);
            bestMin = min(bestMin, currentMin);
        }
        // All-negative input: the wrapped case would select an empty subarray.
        if (bestMax < 0) return bestMax;
        return max(bestMax, total - bestMin);
    }
};

// Approach: Sort by start, then extend the last merged interval whenever the next one overlaps.
// Time O(n log n), Space O(n)
class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end());
        vector<vector<int>> merged;
        for (const auto& interval : intervals) {
            if (!merged.empty() && interval[0] <= merged.back()[1]) {
                merged.back()[1] = max(merged.back()[1], interval[1]);
            } else {
                merged.push_back(interval);
            }
        }
        return merged;
    }
};

// Approach: Slow and fast pointers; when fast reaches the end, slow is at the middle.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* middleNode(ListNode* head) {
        ListNode* slow = head;
        ListNode* fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        return slow;
    }
};

// Approach: Scan once, counting unmatched open brackets and closers that have no partner.
// Time O(n), Space O(1)
class Solution {
public:
    int minAddToMakeValid(string s) {
        int unmatchedOpen = 0;
        int unmatchedClose = 0;
        for (char ch : s) {
            if (ch == '(') {
                unmatchedOpen++;
            } else if (unmatchedOpen > 0) {
                unmatchedOpen--;
            } else {
                unmatchedClose++;
            }
        }
        return unmatchedOpen + unmatchedClose;
    }
};

// Approach: Sort by end coordinate and shoot at the end of each balloon not yet burst.
// Time O(n log n), Space O(1) extra
class Solution {
public:
    int findMinArrowShots(vector<vector<int>>& points) {
        // Compare without subtracting: coordinates can reach +-2^31.
        sort(points.begin(), points.end(),
             [](const vector<int>& a, const vector<int>& b) { return a[1] < b[1]; });
        int arrows = 0;
        long long lastArrow = LLONG_MIN;
        for (const auto& balloon : points) {
            if (arrows == 0 || balloon[0] > lastArrow) {
                arrows++;
                lastArrow = balloon[1];
            }
        }
        return arrows;
    }
};

// Approach: Sliding window with needed-character counts, shrinking from the left once covered.
// Time O(n + m), Space O(alphabet)
class Solution {
public:
    string minWindow(string s, string t) {
        unordered_map<char, int> need;
        for (char ch : t) need[ch]++;
        int missing = t.size();
        int n = s.size();
        int bestLength = n + 1;
        int bestStart = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            if (need[s[right]] > 0) missing--;
            need[s[right]]--;
            if (missing == 0) {
                // Drop characters that the window holds in surplus.
                while (need[s[left]] < 0) {
                    need[s[left]]++;
                    left++;
                }
                if (right - left + 1 < bestLength) {
                    bestLength = right - left + 1;
                    bestStart = left;
                }
                // Release the leftmost needed character to look for the next window.
                need[s[left]]++;
                missing++;
                left++;
            }
        }
        return bestLength > n ? "" : s.substr(bestStart, bestLength);
    }
};

// Approach: Backtracking over rows with bitmasks for used columns and both diagonals.
// Time O(n!), Space O(n)
int countPlacements(int fullMask, int columns, int diagonal, int antiDiagonal) {
    if (columns == fullMask) return 1;
    int total = 0;
    int available = fullMask & ~(columns | diagonal | antiDiagonal);
    while (available) {
        int bit = available & -available;
        available -= bit;
        total += countPlacements(fullMask, columns | bit, ((diagonal | bit) << 1) & fullMask,
                                 (antiDiagonal | bit) >> 1);
    }
    return total;
}

class Solution {
public:
    int totalNQueens(int n) {
        return countPlacements((1 << n) - 1, 0, 0, 0);
    }
};

// Approach: Find the rightmost ascent, swap with the next larger suffix value, reverse the suffix.
// Time O(n), Space O(1)
class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int n = nums.size();
        int pivot = n - 2;
        while (pivot >= 0 && nums[pivot] >= nums[pivot + 1]) pivot--;
        if (pivot >= 0) {
            int swapIndex = n - 1;
            while (nums[swapIndex] <= nums[pivot]) swapIndex--;
            swap(nums[pivot], nums[swapIndex]);
        }
        reverse(nums.begin() + pivot + 1, nums.end());
    }
};

// Approach: Union-Find; every successful union merges two components into one.
// Time O((n + E) * alpha(n)), Space O(n)
class Solution {
public:
    int countComponents(int n, vector<vector<int>>& edges) {
        vector<int> parent(n);
        iota(parent.begin(), parent.end(), 0);
        function<int(int)> findRoot = [&](int node) {
            while (parent[node] != node) {
                parent[node] = parent[parent[node]];
                node = parent[node];
            }
            return node;
        };
        int components = n;
        for (const auto& edge : edges) {
            int rootA = findRoot(edge[0]);
            int rootB = findRoot(edge[1]);
            if (rootA != rootB) {
                parent[rootA] = rootB;
                components--;
            }
        }
        return components;
    }
};

// Approach: Rewire into separate odd and even chains, then attach the even chain after the odd.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* oddEvenList(ListNode* head) {
        if (!head || !head->next) return head;
        ListNode* odd = head;
        ListNode* even = head->next;
        ListNode* evenHead = even;
        while (even && even->next) {
            odd->next = even->next;
            odd = odd->next;
            even->next = odd->next;
            even = even->next;
        }
        odd->next = evenHead;
        return head;
    }
};

// Approach: Precompute palindromic substrings, then count partitions with a prefix DP.
// Time O(n^2), Space O(n^2)
class Solution {
public:
    int partition(string s) {
        int n = s.size();
        vector<vector<bool>> isPalindrome(n, vector<bool>(n, false));
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                bool innerOk = j - i < 2 || isPalindrome[i + 1][j - 1];
                isPalindrome[i][j] = s[i] == s[j] && innerOk;
            }
        }
        // ways[i] is the number of partitions of the prefix s[0..i).
        vector<long long> ways(n + 1, 0);
        ways[0] = 1;
        for (int end = 1; end <= n; end++) {
            for (int start = 0; start < end; start++) {
                if (isPalindrome[start][end - 1]) ways[end] += ways[start];
            }
        }
        return ways[n];
    }
};

// Approach: Record each letter's last index, then cut whenever the scan reaches the part's end.
// Time O(n), Space O(1)
class Solution {
public:
    vector<int> partitionLabels(string s) {
        int n = s.size();
        int lastIndex[26];
        for (int i = 0; i < n; i++) {
            lastIndex[s[i] - 'a'] = i;
        }
        vector<int> sizes;
        int partStart = 0;
        int partEnd = 0;
        for (int i = 0; i < n; i++) {
            partEnd = max(partEnd, lastIndex[s[i] - 'a']);
            if (i == partEnd) {
                sizes.push_back(i - partStart + 1);
                partStart = i + 1;
            }
        }
        return sizes;
    }
};

// Approach: DFS subtracting node values; succeed at a leaf whose value equals what remains.
// Time O(n), Space O(h)
class Solution {
public:
    bool hasPathSum(TreeNode* root, int targetSum) {
        if (!root) return false;
        if (!root->left && !root->right) return root->val == targetSum;
        int remaining = targetSum - root->val;
        return hasPathSum(root->left, remaining) || hasPathSum(root->right, remaining);
    }
};

// Approach: DP where dp[i] is the fewest squares summing to i, trying every square below i.
// Time O(n * sqrt(n)), Space O(n)
class Solution {
public:
    int numSquares(int n) {
        vector<int> dp(n + 1, n);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            for (int root = 1; root * root <= i; root++) {
                dp[i] = min(dp[i], dp[i - root * root] + 1);
            }
        }
        return dp[n];
    }
};

// Approach: A positive power of two has one set bit, so n & (n - 1) clears it to zero.
// Time O(1), Space O(1)
class Solution {
public:
    bool isPowerOfTwo(int n) {
        return n > 0 && (n & (n - 1)) == 0;
    }
};

// Approach: DP over prefixes; '*' either drops its pair or consumes one more matching character.
// Time O(m * n), Space O(m * n)
class Solution {
public:
    bool isMatch(string s, string p) {
        int m = s.size();
        int n = p.size();
        // dp[i][j] is true when s[0..i) matches p[0..j).
        vector<vector<bool>> dp(m + 1, vector<bool>(n + 1, false));
        dp[0][0] = true;
        for (int i = 0; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (p[j - 1] == '*') {
                    dp[i][j] = dp[i][j - 2];
                    bool repeatable = i > 0 && (p[j - 2] == '.' || p[j - 2] == s[i - 1]);
                    if (repeatable) dp[i][j] = dp[i][j] || dp[i - 1][j];
                } else if (i > 0 && (p[j - 1] == '.' || p[j - 1] == s[i - 1])) {
                    dp[i][j] = dp[i - 1][j - 1];
                }
            }
        }
        return dp[m][n];
    }
};

// Approach: Dummy head and a trailing pointer; skip entire runs of repeated values.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* deleteDuplicates(ListNode* head) {
        ListNode dummy(0);
        dummy.next = head;
        ListNode* prev = &dummy;
        while (head) {
            if (head->next && head->next->val == head->val) {
                int duplicateValue = head->val;
                while (head && head->val == duplicateValue) head = head->next;
                prev->next = head;
            } else {
                prev = head;
                head = head->next;
            }
        }
        return dummy.next;
    }
};

// Approach: Split at the middle, reverse the second half, then interleave the two halves.
// Time O(n), Space O(1)
class Solution {
public:
    void reorderList(ListNode* head) {
        if (!head || !head->next) return;
        ListNode* slow = head;
        ListNode* fast = head;
        while (fast->next && fast->next->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        ListNode* second = slow->next;
        ListNode* reversed = nullptr;
        slow->next = nullptr;
        while (second) {
            ListNode* next = second->next;
            second->next = reversed;
            reversed = second;
            second = next;
        }
        ListNode* first = head;
        second = reversed;
        while (second) {
            ListNode* firstNext = first->next;
            ListNode* secondNext = second->next;
            first->next = second;
            second->next = firstNext;
            first = firstNext;
            second = secondNext;
        }
    }
};

// Approach: Walk the list once, pointing each node back at its predecessor.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        ListNode* prev = nullptr;
        while (head) {
            ListNode* next = head->next;
            head->next = prev;
            prev = head;
            head = next;
        }
        return prev;
    }
};

// Approach: Add each symbol's value, subtracting it when a larger symbol follows.
// Time O(n), Space O(1)
class Solution {
public:
    int romanToInt(string s) {
        auto valueOf = [](char symbol) {
            switch (symbol) {
                case 'I': return 1;
                case 'V': return 5;
                case 'X': return 10;
                case 'L': return 50;
                case 'C': return 100;
                case 'D': return 500;
                default: return 1000;
            }
        };
        int total = 0;
        for (size_t i = 0; i < s.size(); i++) {
            if (i + 1 < s.size() && valueOf(s[i]) < valueOf(s[i + 1])) {
                total -= valueOf(s[i]);
            } else {
                total += valueOf(s[i]);
            }
        }
        return total;
    }
};

// Approach: Close the list into a ring, then cut it after the (n - k)th node.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        if (!head || !head->next || k == 0) return head;
        int length = 1;
        ListNode* tail = head;
        while (tail->next) {
            tail = tail->next;
            length++;
        }
        k %= length;
        if (k == 0) return head;
        tail->next = head;
        ListNode* newTail = head;
        for (int i = 0; i < length - k - 1; i++) {
            newTail = newTail->next;
        }
        ListNode* newHead = newTail->next;
        newTail->next = nullptr;
        return newHead;
    }
};

// Approach: Binary search treating the row-major matrix as one sorted array.
// Time O(log(m * n)), Space O(1)
class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        if (matrix.empty() || matrix[0].empty()) return false;
        int rows = matrix.size();
        int cols = matrix[0].size();
        int low = 0;
        int high = rows * cols - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int value = matrix[mid / cols][mid % cols];
            if (value == target) return true;
            if (value < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return false;
    }
};

// Approach: Use the first row and column as zero markers, remembering whether they need clearing.
// Time O(m * n), Space O(1)
class Solution {
public:
    void setZeroes(vector<vector<int>>& matrix) {
        int m = matrix.size();
        int n = matrix[0].size();
        bool firstRowHasZero = false;
        bool firstColHasZero = false;
        for (int j = 0; j < n; j++) {
            if (matrix[0][j] == 0) firstRowHasZero = true;
        }
        for (int i = 0; i < m; i++) {
            if (matrix[i][0] == 0) firstColHasZero = true;
        }
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (matrix[i][j] == 0) matrix[i][0] = matrix[0][j] = 0;
            }
        }
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (matrix[i][0] == 0 || matrix[0][j] == 0) matrix[i][j] = 0;
            }
        }
        if (firstRowHasZero) {
            for (int j = 0; j < n; j++) matrix[0][j] = 0;
        }
        if (firstColHasZero) {
            for (int i = 0; i < m; i++) matrix[i][0] = 0;
        }
    }
};

// Approach: Track bits seen once and twice with two masks; bits seen three times reset.
// Time O(n), Space O(1)
class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int seenOnce = 0;
        int seenTwice = 0;
        for (int num : nums) {
            seenOnce = (seenOnce ^ num) & ~seenTwice;
            seenTwice = (seenTwice ^ num) & ~seenOnce;
        }
        return seenOnce;
    }
};

// Approach: Top-down merge sort; split at the middle and merge the sorted halves.
// Time O(n log n), Space O(log n)
ListNode* mergeSorted(ListNode* a, ListNode* b) {
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

class Solution {
public:
    ListNode* sortList(ListNode* head) {
        if (!head || !head->next) return head;
        ListNode* slow = head;
        ListNode* fast = head->next;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        ListNode* second = slow->next;
        slow->next = nullptr;
        return mergeSorted(sortList(head), sortList(second));
    }
};

// Approach: Binary search for the largest integer whose square is at most x.
// Time O(log x), Space O(1)
class Solution {
public:
    int mySqrt(int x) {
        long long low = 0;
        long long high = x;
        while (low < high) {
            long long mid = (low + high + 1) / 2;
            if (mid * mid <= x) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }
};

// Approach: At every node of root, test whether the subtree rooted there equals subRoot.
// Time O(n * m), Space O(h)
bool isSameTree(TreeNode* a, TreeNode* b) {
    if (!a || !b) return a == b;
    return a->val == b->val && isSameTree(a->left, b->left) && isSameTree(a->right, b->right);
}

class Solution {
public:
    bool isSubtree(TreeNode* root, TreeNode* subRoot) {
        if (!root) return false;
        return isSameTree(root, subRoot) || isSubtree(root->left, subRoot) ||
               isSubtree(root->right, subRoot);
    }
};

// Approach: DFS carrying the number formed so far and summing it at each leaf.
// Time O(n), Space O(h)
int sumPaths(TreeNode* node, int pathValue) {
    if (!node) return 0;
    pathValue = pathValue * 10 + node->val;
    if (!node->left && !node->right) return pathValue;
    return sumPaths(node->left, pathValue) + sumPaths(node->right, pathValue);
}

class Solution {
public:
    int sumNumbers(TreeNode* root) {
        return sumPaths(root, 0);
    }
};

// Approach: Dijkstra-style search on a min-heap, where a path costs its highest cell.
// Time O(n^2 log n), Space O(n^2)
class Solution {
public:
    int swimInWater(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<vector<bool>> visited(n, vector<bool>(n, false));
        // Heap entries are (time needed to reach the cell, row, column).
        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> heap;
        heap.push({grid[0][0], 0, 0});
        visited[0][0] = true;
        const int dRow[] = {1, -1, 0, 0};
        const int dCol[] = {0, 0, 1, -1};
        while (!heap.empty()) {
            auto [time, row, col] = heap.top();
            heap.pop();
            if (row == n - 1 && col == n - 1) return time;
            for (int d = 0; d < 4; d++) {
                int nextRow = row + dRow[d];
                int nextCol = col + dCol[d];
                bool inside = nextRow >= 0 && nextRow < n && nextCol >= 0 && nextCol < n;
                if (inside && !visited[nextRow][nextCol]) {
                    visited[nextRow][nextCol] = true;
                    heap.push({max(time, grid[nextRow][nextCol]), nextRow, nextCol});
                }
            }
        }
        return 0;
    }
};

// Approach: The most frequent task sets the frame length; idle slots only pad it.
// Time O(T), Space O(1)
class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        vector<int> count(26, 0);
        for (char task : tasks) {
            count[task - 'A']++;
        }
        int maxCount = *max_element(count.begin(), count.end());
        int tasksWithMax = 0;
        for (int c : count) {
            if (c == maxCount) {
                tasksWithMax++;
            }
        }
        int totalTasks = tasks.size();
        int frameLength = (maxCount - 1) * (n + 1) + tasksWithMax;
        return max(totalTasks, frameLength);
    }
};

// Approach: One pass with a hash map from value to index, looking up each complement.
// Time O(n), Space O(n)
class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<long long, int> seenAt;
        for (int i = 0; i < (int)nums.size(); i++) {
            auto it = seenAt.find((long long)target - nums[i]);
            if (it != seenAt.end()) return {it->second, i};
            seenAt[nums[i]] = i;
        }
        return {};
    }
};

// Approach: Row-by-row DP; each cell's path count is the cell above plus the cell to the left.
// Time O(m * n), Space O(n)
class Solution {
public:
    int uniquePaths(int m, int n) {
        vector<int> paths(n, 1);
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                paths[j] += paths[j - 1];
            }
        }
        return paths[n - 1];
    }
};

// Approach: Two pointers moving inward, skipping non-alphanumerics and ignoring case.
// Time O(n), Space O(1)
class Solution {
public:
    bool isPalindrome(string s) {
        int left = 0;
        int right = (int)s.size() - 1;
        while (left < right) {
            while (left < right && !isalnum((unsigned char)s[left])) left++;
            while (left < right && !isalnum((unsigned char)s[right])) right--;
            if (tolower((unsigned char)s[left]) != tolower((unsigned char)s[right])) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
};

// Approach: Track digits already seen in each row, column and 3x3 box.
// Time O(1), Space O(1)
class Solution {
public:
    bool isValidSudoku(vector<vector<char>>& board) {
        bool inRow[9][9] = {};
        bool inCol[9][9] = {};
        bool inBox[9][9] = {};
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') {
                    continue;
                }
                int digit = board[r][c] - '1';
                int box = (r / 3) * 3 + c / 3;
                if (inRow[r][digit] || inCol[c][digit] || inBox[box][digit]) {
                    return false;
                }
                inRow[r][digit] = true;
                inCol[c][digit] = true;
                inBox[box][digit] = true;
            }
        }
        return true;
    }
};

// Approach: DP where canBreak[i] means the first i characters can be segmented.
// Time O(n^2 * L), Space O(n + total dictionary size), L = longest substring hashed
class Solution {
public:
    bool wordBreak(string s, vector<string>& wordDict) {
        unordered_set<string> dict(wordDict.begin(), wordDict.end());
        int n = s.size();
        vector<bool> canBreak(n + 1, false);
        canBreak[0] = true;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i && !canBreak[i]; j++) {
                if (canBreak[j] && dict.count(s.substr(j, i - j))) {
                    canBreak[i] = true;
                }
            }
        }
        return canBreak[n];
    }
};
